-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 4: ligar as imagens às questões. SÓ DEPOIS do envio das imagens ao depósito
-- "question-figures" (o Claude roda scripts/carga-provas/subir-imagens.mjs --enviar quando você autorizar) e DEPOIS das partes 2 e 3.
-- Gerado por scripts/carga-provas/gerar-pacote.mjs (ramo carga-provas). Não edite à mão.
-- O que faz:
--   * confere que os 79 arquivos estão no depósito com o tamanho certo; se faltar algum, PARA sem mudar nada;
--   * registra cada arquivo como conferido (ch_worker_question_figure_confirm, a mesma função do servidor) e o reserva à questão;
--   * liga 77 questões: 56 tabelas viram imagem (o trecho achatado da tabela sai do enunciado), 5 figuras que faltavam
--     (2024/2 Q46 e Q60: a imagem nova SUBSTITUI a antiga) e as figuras e tabelas da 2026/2;
--   * liga a marca "cita figura" nessas questões e em 10 questões que já têm figura e estavam com a marca desligada (apontadas pelos relatórios);
--   * só mexe na questão cujas figuras e enunciado ainda são os esperados; senão PULA e lista. O antes fica no histórico.
-- Como colar: editor SQL do Supabase, arquivo INTEIRO, Run. Primeira linha: "OK: ..." (ou "ATENÇÃO:"; mostre ao Claude).
-- Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_imagens_resultado (questao text, situacao text, detalhe text);
delete from _carga_imagens_resultado;

do $carga_imagens$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"enamed_2025_q010","code":"ENAMED-2025-Q010","imagens":[{"path":"questoes/7ff83c43707281764a3a28a3713cd6b2.png","alt":"Tabela de 3 colunas (Exame, Resultado, Valor de referência) com 5 linhas de exames laboratoriais: hemoglobina, leucócitos, plaquetas, creatinina e ureia, com unidades.","sha256":"20afbc7f653341efd726d86ae733c853193eff3270efe94258730244c5ef3cd9","source_page":4}],"imagens_antes":[],"enunciado_antes_md5":"73986d177fd2f57e24c27b131f54d49d","enunciado_depois":"Paciente feminina de 78 anos, com 24 horas de evolução de dor e abaulamento progressivo em região inguinal direita. Apresentou também alguns episódios de vômitos e diminuição da eliminação de flatos. Antecedentes: neoplasia de mama há 30 anos, diabetes mellitus há 20 anos e tabagista de 40 maços/ano. Ao exame estava normotensa, eucárdica, afebril, eupneica. Índice de massa corporal de 35 kg/m². Abdome globoso, depressível, com abaulamento não redutível e desconforto à palpação em região inguinal direita, com discreta hiperemia local e sem sinais de irritação peritoneal. Resultados dos exames laboratoriais: A hipótese diagnóstica mais provável é","tamanhos":{"questoes/7ff83c43707281764a3a28a3713cd6b2.png":33070}},{"id":"enamed_2025_q015","code":"ENAMED-2025-Q015","imagens":[{"path":"questoes/c4e29036b28ba62fe107f0e60e016403.png","alt":"Tabela de 3 colunas (Exame, Resultado, Valor de referência) com 9 linhas: pressão arterial, peso, hematócrito, glicemia, albumina sérica, creatinina, triglicerídeos, proteína urinária de 24 horas e sedimentos.","sha256":"699868d3d8110717bf5855faa9c6408bd914fdee131daff6404195783a0a2e32","source_page":6}],"imagens_antes":[],"enunciado_antes_md5":"b81146ccb1b069ee0823502d15cf2c1c","enunciado_depois":"Homem de 50 anos, queixando-se de astenia e constipação com fezes em fita. Há 15 dias, apresenta edema de membros inferiores até a raiz da região crural, bilateralmente, com pouca melhora à elevação dos membros. Ele perdeu 10 kg em 6 meses. Nega hipertensão arterial e diabetes mellitus e não faz uso de medicamento. Os exames do paciente apresentaram os seguintes resultados: Dentre esses achados laboratoriais, quais são necessários para a definição da síndrome renal do paciente?","tamanhos":{"questoes/c4e29036b28ba62fe107f0e60e016403.png":61629}},{"id":"enamed_2025_q024","code":"ENAMED-2025-Q024","imagens":[{"path":"questoes/332896656da0e1c81edddc6d16b1f236.png","alt":"Tabela de 3 colunas (Exame, Resultado, Valor de referência) com 7 linhas: hemoglobina, hematócrito, leucócitos totais, bastonetes, urina, hemácias e beta-hCG sérico, com unidades.","sha256":"47dafa43de18017c66de5697dd20218fe9713fcaa123f90b707d01253850491b","source_page":8}],"imagens_antes":[],"enunciado_antes_md5":"dc7f79c7318173cc21b0d690f85a33d0","enunciado_depois":"Paciente do sexo feminino, 27 anos, é atendida em Unidade de Pronto Atendimento (UPA) com história de dor abdominal, com início em epigástrio há dois dias, contínua, sem fatores de melhora, associada a náuseas e perda de apetite, evoluindo para dor em fossa ilíaca direita há 1 dia e febre de 38,2 ºC no dia do atendimento. Nega comorbidades, cirurgias prévias ou uso de medicações regulares. Relata que a última menstruação foi há 23 dias, e apresenta ciclos regulares de 28 dias. Exame físico: regular estado geral, corada, desidratada +/4+, eupneica, anictérica, acianótica; ausculta pulmonar e cardíaca sem alterações; ruídos hidroaéreos diminuídos, descompressão brusca dolorosa em quadrante inferior de abdome à direita. Considerando o diagnóstico mais provável, a conduta adequada é","tamanhos":{"questoes/332896656da0e1c81edddc6d16b1f236.png":43907}},{"id":"enamed_2025_q038","code":"ENAMED-2025-Q038","imagens":[{"path":"questoes/58bdc6142f4f6cdc2903b3fc5073297c.png","alt":"Tabela de 3 colunas (Exame, Resultado, Valor de referência) com 12 linhas de exames: hematócrito, hemoglobina, leucócitos, glicose, bilirrubina total, ureia, cálcio, amilase, lipase, fosfatase alcalina, LDH e TGO.","sha256":"08781c7e8fb31e5c2b02b7d67a522770ecad9e49198577fb125ca0b9ffd7d37b","source_page":11}],"imagens_antes":[],"enunciado_antes_md5":"7b7a8dcf32f7d2a2cb0f94a5a3a1e67e","enunciado_depois":"Homem de 58 anos deu entrada no pronto-socorro com dor epigástrica irradiada para as costas, iniciada há 2 horas, progressiva, pós-prandial, acompanhada de náuseas, vômitos e sudorese. Relata episódios semelhantes no último ano, que melhoraram com uso de analgésico. Tabagista ativo, alcoolista de 8 doses de destilado por dia há 33 anos, nega comorbidades. Exame físico: corado, acianótico, anictérico, sudoreico, fácies de dor, agitado. Índice de massa corporal de 23 kg/m²; pressão arterial de 150 x 90 mmHg; frequência cardíaca de 74 bpm; frequência respiratória de 18 irpm; temperatura axilar de 37 ºC. Abdome globoso, distendido, timpânico, peristalse presente, doloroso à palpação do epigástrio e hipocôndrio esquerdo. Os exames laboratoriais apresentam os seguintes resultados: Qual é o provável diagnóstico?","tamanhos":{"questoes/58bdc6142f4f6cdc2903b3fc5073297c.png":61819}},{"id":"enamed_2025_q041","code":"ENAMED-2025-Q041","imagens":[{"path":"questoes/d415a8bac948e8588fb3064fd499ac0d.png","alt":"Tabela de 3 colunas (Exame, Resultado, Valor de referência) com 5 linhas: glicemia, gasometria arterial (pH), bicarbonato, creatinina e potássio sérico, com unidades.","sha256":"5964600ac2f7b7f64913049cb4542ff2ff2916b837f109687e2d52feabb4f1fd","source_page":12}],"imagens_antes":[],"enunciado_antes_md5":"f919dbb8d2a278e9041c9cb114475969","enunciado_depois":"Homem de 21 anos, portador de diabetes mellitus tipo 1, diagnosticado há 5 anos, foi levado à Unidade de Pronto Atendimento (UPA) devido à dor abdominal, náuseas e vômitos. Familiares informam que está sem utilizar insulina há 3 dias por dificuldades financeiras. No exame físico, encontra-se torporoso, desidratado, com hálito cetótico e dor abdominal à palpação profunda de forma generalizada. Ao exame, frequência cardíaca de 112 bpm; frequência respiratória de 38 irpm; pressão arterial de 110 x 70 mmHg. Os exames laboratoriais na admissão indicam: O diagnóstico e a conduta inicial indicada para esse paciente são, respectivamente,","tamanhos":{"questoes/d415a8bac948e8588fb3064fd499ac0d.png":33032}},{"id":"enamed_2025_q046","code":"ENAMED-2025-Q046","imagens":[{"path":"questoes/0984f5c92c10cda61b08cd27457d70a8.png","alt":"Tabela sem cabeçalho, com 2 colunas: anticorpo ou antígeno (ANA, anti-DNA dupla hélice, HLA-B27, fator reumatoide, anti-CCP, anti-Ro, anti-La) e o resultado de cada um.","sha256":"02148e472ae945e36fb797a9a6c6be475265a44e3bdd8be75e5972f9afde1343","source_page":13}],"imagens_antes":[],"enunciado_antes_md5":"68906e59db5b8352cbccfb7a0fadee99","enunciado_depois":"Homem de 32 anos apresenta quadro de dor lombar crônica de início insidioso, com duração aproximada de 6 meses, que piora pela manhã e melhora com o movimento. Refere rigidez matinal, principalmente nas regiões lombar e sacroilíaca, com duração de mais de 30 minutos, com dor nas articulações sacroilíacas e sensação de fadiga durante as últimas semanas. Não há histórico de trauma. A história familiar é positiva para doenças reumatológicas, mas o paciente desconhece diagnósticos específicos. O painel de autoanticorpos apresenta: Com base no caso clínico e nos exames laboratoriais apresentados, qual é o diagnóstico mais provável?","tamanhos":{"questoes/0984f5c92c10cda61b08cd27457d70a8.png":46146}},{"id":"enamed_2025_q095","code":"ENAMED-2025-Q095","imagens":[{"path":"questoes/1802105596ae7327b4a6ace015cda3ee.png","alt":"Tabela de 3 colunas (nome do exame, Resultados, Valores de referência) com 13 linhas de hemograma: hemoglobina, hematócrito, VCM, HCM, CHCM, RDW, leucócitos totais, neutrófilos, eosinófilos, basófilos, monócitos, linfócitos e plaquetas.","sha256":"17d2c2426396c16b4876f1dbb74b088a907efbcbb6d3c0d6057a3f2901ecb809","source_page":24}],"imagens_antes":[],"enunciado_antes_md5":"85f7af2e789cd96ff689908867fad552","enunciado_depois":"Menina de 11 anos é levada pela mãe à consulta médica em Unidade Básica de Saúde (UBS), com história de cansaço, palidez cutânea e baixo rendimento escolar nos últimos 3 meses. Ao exame físico, mucosas hipocrômicas (3+/4+); palidez cutânea. Pulso radial: 104 bpm, rítmico e cheio. Aparelho cardiovascular: sopro sistólico 2/6. Restante do exame físico sem alterações. Mãe apresenta hemograma da menina realizado há 2 semanas. Diante do caso apresentado, assinale a alternativa mais adequada.","tamanhos":{"questoes/1802105596ae7327b4a6ace015cda3ee.png":67429}},{"id":"enamed_2025_q098","code":"ENAMED-2025-Q098","imagens":[{"path":"questoes/85ba2745376ea1e153dea89cbf9dffeb.png","alt":"Tabela de 3 colunas (Exame, Resultado, Valor de referência) com 12 linhas: hematócrito, leucócitos totais, bastões, creatinina, TGO, TGP, fosfatase alcalina, gama GT, bilirrubina total, bilirrubina direta e amilase.","sha256":"397320371b538ab1ab2ec23f16c84830d22630677283bf8eb5be6534e58dce57","source_page":26}],"imagens_antes":[],"enunciado_antes_md5":"8c9aec1da91359d965c9b03157b101de","enunciado_depois":"Paciente de 43 anos, sexo feminino, internada em enfermaria de cirurgia. Refere icterícia, colúria e acolia, iniciadas há 72 horas. Paciente nega tabagismo, comorbidades ou episódios semelhantes previamente. Exame físico: ictérica (+++/++++), dor à palpação profunda de hipocôndrio direito; frequência cardíaca de 83 bpm; pressão arterial de 123 x 76 mmHg; temperatura axilar de 37,4 ºC. Ultrassonografia de abdome: presença de múltiplas imagens móveis e arredondadas, de 0,5 a 1 cm de diâmetro, e dilatação de vias biliares intra e extra-hepáticas. Exames laboratoriais: Nesse momento, quais são, respectivamente, o diagnóstico sindrômico e o exame complementar mais indicados para prosseguir à investigação?","tamanhos":{"questoes/85ba2745376ea1e153dea89cbf9dffeb.png":59302}},{"id":"revalida_2020_1_q025","code":"REV-2020-Q025","imagens":[{"path":"questoes/9ecc73a42da792f5f088c844ce0a3a82.png","alt":"Gráfico de IMC por idade para meninos de 5 a 19 anos, em escores-z. Mostra curvas de -3 a 3, idade no eixo horizontal e IMC em kg/m² no vertical. Fonte: WHO, 2007.","sha256":"1c177d9d9df9fc0ec33974fb77b8372d54f863784c8907f4f740f54f0616aef6","source_page":12}],"imagens_antes":[],"enunciado_antes_md5":"40d6cf3cc729a849ef2eb17dac51990e","enunciado_depois":null,"tamanhos":{"questoes/9ecc73a42da792f5f088c844ce0a3a82.png":594061}},{"id":"revalida_2020_1_q047","code":"REV-2020-Q047","imagens":[{"path":"questoes/e95ba94abe1644ab50dcc3349d216d91.png","alt":"Quadro com as capitais brasileiras em linhas e, nas colunas, mortes confirmadas por COVID-19, população estimada em 2019, mortalidade por 100 mil e proporção de pessoas com renda per capita menor que US$ 5,5 por dia.","sha256":"799a5e17d5371ca63fe56c64b66f13cbcb6d9ec207cb03de732facb841eb2bf2","source_page":22}],"imagens_antes":[],"enunciado_antes_md5":"fc37ff36696f796995c70c6219893323","enunciado_depois":null,"tamanhos":{"questoes/e95ba94abe1644ab50dcc3349d216d91.png":470657}},{"id":"revalida_2021_1_q031","code":"REV-2021-Q031","imagens":[{"path":"questoes/a1c875c53347f9a93e733437270bbd45.png","alt":"Tabela de urocultura de homem de 52 anos: amostra de urina com cultura positiva, 100 000 UFC de E. coli, e antibiograma com 14 antibióticos, cada um com classificação (sensível ou resistente) e concentração inibitória mínima.","sha256":"632b8dca93c49c955b1733083c19c06d2e436ddd5f0ca55635222937e165b962","source_page":9}],"imagens_antes":[],"enunciado_antes_md5":"9b7c591998b8486080e67fb852a236e9","enunciado_depois":"Um homem de 52 anos de idade procura atendimento médico em nível ambulatorial após 7 dias de uma internação hospitalar de 72 horas para correção de uma hérnia inguinal, na qual permaneceu 24 horas com sonda vesical de demora. O paciente encontra-se em bom estado de saúde, queixando-se de leve dor no local da cirurgia e de disúria, iniciada há 3 dias, além de polaciúria. Ao exame, a ferida operatória encontra-se limpa e apresenta dor à palpação profunda do hipogástrio. No mais, o exame físico é completamente normal. Possui comorbidades, pois é diabético e portador de epilepsia em uso de topiramato para essa última condição. O médico assistente solicitou uma urocultura, cujo resultado segue abaixo. Nesse caso, a conduta do médico deve ser","tamanhos":{"questoes/a1c875c53347f9a93e733437270bbd45.png":78027}},{"id":"revalida_2022_1_q048","code":"REV-2022.1-Q048","imagens":[{"path":"questoes/07215e9d3b27b77cff6df4ce07918f8f.png","alt":"Quadro de exames de uma criança com febre: hemoglobina, hematócrito, leucócitos, plaquetas, RT-PCR para SARS-CoV-2, ferritina, albumina, PCR, ureia, creatinina e sorologias para dengue, com valor encontrado e valor de referência.","sha256":"4d7b1cb5a7ad9cc2c68effb8a9188b061b8819555218846892643ae2d0cfc90a","source_page":14}],"imagens_antes":[],"enunciado_antes_md5":"8e274aab6aee2134bd9ee7c8a0ca3fae","enunciado_depois":"Um pré-escolar com 4 anos de idade, acompanhado dos pais, dá entrada na emergência com quadro de febre, cefaleia e irritabilidade que se iniciou há 2 dias. A mãe relata que, hoje pela manhã, a criança apresentou erupções vermelhas na pele e que não percebeu outros sintomas antes do início do aparecimento desse quadro, porém, conta que o pai da criança estava com sintomas de síndrome gripal 2 semanas antes do adoecimento do filho. Ao exame físico, a criança apresenta estado geral comprometido, mucosas hipocoradas +/4+ e escleróticas anictéricas. Apresenta, ainda, olhos com conjuntivas hiperemiadas; pescoço com linfoadenomegalia cervical; tórax com diminuição da expansibilidade e tiragem subcostal presente; abdome plano, sem visceromegalias; pele com presença de erupções exantematosas. Frequência cardíaca = 168 batimentos por minuto, frequência respiratória = 39 incursões respiratórias por minuto e temperatura axilar = 39,1 °C. Os resultados dos exames laboratoriais iniciais da criança são apresentados no quadro a seguir. Após análise do quadro clínico e dos resultados laboratoriais, a principal hipótese diagnóstica é","tamanhos":{"questoes/07215e9d3b27b77cff6df4ce07918f8f.png":89085}},{"id":"revalida_2022_1_q071","code":"REV-2022.1-Q071","imagens":[{"path":"questoes/19f271b06d0356738bbdcc8621f290ac.png","alt":"Quadro de exames de uma mulher com dores articulares: hemograma, creatinina, ureia, transaminases, bilirrubinas, pesquisa de autoanticorpos, fator reumatoide e plaquetas, com valor encontrado e valor de referência.","sha256":"01347884ab98467b4d83f06a00bba363386026775fbddb2b4fafdf2e3006b0cb","source_page":20}],"imagens_antes":[],"enunciado_antes_md5":"a0da36aaaa4ff3a1d3131fe6bb08a53a","enunciado_depois":"Uma mulher com 33 anos de idade procura o ambulatório de clínica médica devido a dores articulares há 3 meses. Refere o acometimento de mãos (interfalangeanas proximais e metacarpofalangeanas), punhos e joelhos. Ao exame físico, apresenta sinais de artrite nessas articulações. Foram solicitados exames laboratoriais para a investigação diagnóstica e os resultados são apresentados a seguir. Diante desses achados clínicos e laboratoriais, quais são, respectivamente, o autoanticorpo relacionado ao FAN apresentado e o diagnóstico pertinente ao caso?","tamanhos":{"questoes/19f271b06d0356738bbdcc8621f290ac.png":104453}},{"id":"revalida_2022_1_q091","code":"REV-2022.1-Q091","imagens":[{"path":"questoes/76d783ee6b3e68be6e40e59e6d11ec7c.png","alt":"Quadro com provas bioquímicas hepáticas (AST, ALT, bilirrubinas, fosfatase alcalina, gama-glutamil transferase, INR e PTTa) e marcadores virais da hepatite, com valor encontrado e valor de referência.","sha256":"7faec81668f6955c5eb69f7d2b853166768f2151de7bccbef353a893fc76f595","source_page":25}],"imagens_antes":[],"enunciado_antes_md5":"544e23ce23824c7c285679413b570664","enunciado_depois":"Um homem com 32 anos de idade, usuário de drogas ilícitas injetáveis (DII), comparece à consulta ambulatorial em clínica médica com queixa de fadiga importante e dor abdominal no hipocôndrio direito que teve início há 1 semana. Refere que, 2 dias antes do início desses sintomas, apresentou febre, artralgias e um exantema leve, que desapareceram, ficando em seguida com os olhos amarelados e a urina escura. Relata que esses últimos sinais apareceram simultaneamente à melhora da febre, que persistiu por alguns dias, e que, nos últimos dias, passou a ter apenas fadiga e dor abdominal. Nega náuseas, vômitos, diarreia ou sangramentos, e afirma conseguir ingerir líquidos e alimentos por via oral de forma normal. Nega comorbidades prévias significativas, e sua história familiar não é relevante. Além do uso de DII, o paciente é tabagista (10 maços/ano) e etilista social de fermentados. Ao exame físico, encontra-se em regular estado geral, com fácies de doença aguda, levemente ictérico nas escleras; corado, hidratado, acianótico, afebril, sem equimoses ou petéquias. Aparelhos cardiovascular e respiratório sem anormalidades. Abdome doloroso à palpação do hipocôndrio direito, sendo o fígado palpável a 3 cm do rebordo costal direito, na linha hemiclavicular, de borda romba e consistência habitual; espaço de Traube livre. Não há edemas em membros inferiores. Os resultados dos exames complementares solicitados nessa consulta são apresentados na tabela a seguir. Considerando as informações apresentadas, a principal hipótese diagnóstica e o tratamento indicado são, respectivamente,","tamanhos":{"questoes/76d783ee6b3e68be6e40e59e6d11ec7c.png":76152}},{"id":"revalida_2023_1_q011","code":"REV-2023.1-Q011","imagens":[{"path":"questoes/9595e07d45aec3db7d08242edbe6bd4d.png","alt":"Três tabelas de exames da paciente, com resultado e valores de referência: hemograma (hemácias, hemoglobina, hematócrito, leucócitos, plaquetas, com valores para mulheres e homens), coagulograma e outros exames laboratoriais, como Coombs e enzima ADAMTS13.","sha256":"36a0475d4ba6ecc399037b6407a25b2e7bab786d6be0ac87d0a7ed6a1a0f8b30","source_page":4}],"imagens_antes":[],"enunciado_antes_md5":"cd504715eef611732c81697979d30230","enunciado_depois":"Uma paciente com 30 anos, branca, procura serviço de emergência devido a sangramento gengival e ao aparecimento de pontos avermelhados nos membros inferiores há 15 dias, com piora progressiva das lesões e fadiga. Nega febre, uso de medicamentos e ingesta de bebidas à base de quinino. Foram solicitados exames que mostraram: Ao exame clínico, notou-se a presença de lesões na pele, com petéquias no dorso do pé e no tornozelo (sola dos pés sem lesões) e hemorragia bolhosa na mucosa bucal. Com base nas informações descritas, a principal hipótese diagnóstica é","tamanhos":{"questoes/9595e07d45aec3db7d08242edbe6bd4d.png":133073}},{"id":"revalida_2023_2_q022","code":"REV-2023.2-Q022","imagens":[{"path":"questoes/22408f433b0701fd5e07a1a2301a5ff2.png","alt":"Tabela de exames laboratoriais com três colunas (exame, resultado e valor de referência): leucócitos, transaminases TGO e TGP, fosfatase alcalina, gama glutamil transferase, bilirrubinas totais e diretas, amilase e proteína C reativa.","sha256":"0c8a78657b751e67e464441720275de60b1d6cd2ef66d8836b940e52163fd297","source_page":7}],"imagens_antes":[],"enunciado_antes_md5":"467ce209ac8dba256c87b8b2b93b433e","enunciado_depois":"Uma mulher de 45 anos procura o pronto-socorro com queixa de dor abdominal há 3 dias em região epigástrica e hipocôndrio direito, de intensidade crescente, associada a náusea e vômitos. Refere sudorese e calafrios, porém não aferiu temperatura corporal. Além disso, apresenta urina de coloração escurecida. A paciente nega episódios anteriores e não possui antecedentes pessoais relevantes. Ao exame físico, apresenta regular estado geral, corada e hidratada; ictérica 2+/4+; frequência cardíaca de 108 batimentos por minuto; pressão arterial de 110 × 70 mmHg; saturação de oxigênio de 97% em ar ambiente; frequência respiratória de 23 incursões respiratórias por minuto; e temperatura axilar de 38,5 °C; abdome doloroso à palpação em região epigástrica e em hipocôndrio direito. Os exames laboratoriais apresentaram o seguinte resultado: Ultrassonografia de abdome: vesícula biliar de paredes finas, com múltiplos pequenos cálculos em seu interior, e moderada dilatação de vias biliares, sem evidência de fator obstrutivo ao método; fígado e pâncreas estavam sem alterações. Acerca do quadro dessa paciente, qual é a principal hipótese diagnóstica e a conduta imediata adequada?","tamanhos":{"questoes/22408f433b0701fd5e07a1a2301a5ff2.png":60990}},{"id":"revalida_2023_2_q044","code":"REV-2023.2-Q044","imagens":[{"path":"questoes/1057c91a674d1e2111078c81454af1fb.png","alt":"Tabela de exames de rotina com duas colunas (exame e resultado): mamografia, ultrassonografia transvaginal, hematócrito, hemoglobina, HDL, LDL, colesterol total, triglicerídeos e glicemia de jejum.","sha256":"b261eff6cc0d6549a8037156f71b6bea974271f542b86f722429128fbce4daa6","source_page":13}],"imagens_antes":[],"enunciado_antes_md5":"47a50480ca7a9761a264f76cd4e17ca7","enunciado_depois":"Uma mulher de 58 anos foi atendida pela primeira vez no ambulatório especializado em climatério. Faz uso de terapia hormonal combinada via oral há 6 anos. Interrompeu o uso há 5 meses, mas voltou a usar a medicação devido aos sintomas intensos de climatério, principalmente devido aos fogachos e ao impacto negativo na relação sexual. Há cinco anos foi internada por um quadro de trombose venosa profunda, porém, desde então, não houve outros episódios. Os exames de rotina recentes são apresentados na tabela a seguir: Diante do caso acima, a conduta mais segura é","tamanhos":{"questoes/1057c91a674d1e2111078c81454af1fb.png":34374}},{"id":"revalida_2023_2_q071","code":"REV-2023.2-Q071","imagens":[{"path":"questoes/a579e0e325d6b9c3f065ca66215b8d4f.png","alt":"Tabela de exames com três colunas (exame, resultado e valor de referência): hemoglobina, hematócrito, leucócitos totais, proteínas totais, albumina, cálcio, creatinina e imunoglobulinas IgA, IgG e IgM na imunoeletroforese.","sha256":"c8c7bb5cfc900c13aa4d2cc7643cf042b85b91e13563fa2c730f323d91badaa8","source_page":20}],"imagens_antes":[],"enunciado_antes_md5":"1261a09ecc9751c42b982501d8c7651a","enunciado_depois":"Um homem de 68 anos retorna do ambulatório de referência devido a dores em coluna torácica e em lombar, de intensidade progressivamente maior nos últimos 3 meses. Os exames realizados apresentaram os seguintes resultados: A radiografia de coluna vertebral mostrou lesões osteolíticas e fraturas vertebrais em T11, T12, L1 e L2. Nas últimas 2 semanas, o paciente apresenta-se excessivamente sonolento. Considerando essas informações, a hipótese diagnóstica e o exame mais adequado para confirmá-la são, respectivamente,","tamanhos":{"questoes/a579e0e325d6b9c3f065ca66215b8d4f.png":57375}},{"id":"revalida_2023_2_q079","code":"REV-2023.2-Q079","imagens":[{"path":"questoes/438e50b436a2d745ad5fb079ccc61860.png","alt":"Duas figuras. Figura 1: desenhos da palpação obstétrica no abdome. Figura 2: gráfico da altura uterina em cm por semanas de gestação, com duas curvas de percentil. Fonte: Ministério da Saúde, 2012.","sha256":"c2e5dbd385a0580b1dfaa3e9252c9cf9734882b28d1db0e06c34b75c4ac53bda","source_page":22}],"imagens_antes":[],"enunciado_antes_md5":"55794cf61272d6d6b127119aff20d574","enunciado_depois":null,"tamanhos":{"questoes/438e50b436a2d745ad5fb079ccc61860.png":577713}},{"id":"revalida_2024_1_q014","code":"REV-2024.1-Q014","imagens":[{"path":"questoes/415295aa3cfc822e02aad40d37c37e4f.png","alt":"Tabela da carteirinha de pré-natal com 8 consultas, de 15/09 a 12/04: data, idade gestacional, pressão arterial, altura uterina, BCF/MF e observações de cada consulta, mais a legenda das siglas.","sha256":"a9059ebb7e02210d9a64650840ec26ab32314263c23a82e48d14dc1f2a3acb7d","source_page":5}],"imagens_antes":[],"enunciado_antes_md5":"9f5744097808b071f90f78c7fbc10bce","enunciado_depois":"Os dados da carteirinha de uma gestante com 28 anos, primigesta, sem intercorrências clínicas prévias à gestação e que foi atendida em uma unidade básica de saúde, estão transcritos a seguir: Com base nesses dados, é correto afirmar que:","tamanhos":{"questoes/415295aa3cfc822e02aad40d37c37e4f.png":123079}},{"id":"revalida_2024_1_q020","code":"REV-2024.1-Q020","imagens":[{"path":"questoes/9acac4ea1f47a396d887d7b839899d2a.png","alt":"Tabela com três indicadores de uma criança de 2 anos e seus escores-Z: estatura para idade, peso para idade e índice de massa corporal para idade.","sha256":"51f9b7b7990e5783a19638eac92c2dfcb8c0ea4e7a829451bb0c497c80631393","source_page":6}],"imagens_antes":[],"enunciado_antes_md5":"bdc41f6f7261ebeeb9c97af561593114","enunciado_depois":"Uma criança com 2 anos é levada por sua mãe à unidade básica de saúde a fim de verificar se a criança está com peso e altura adequados para a idade. Ao realizar o exame clínico da criança, o médico observa os seguintes dados. A partir dos dados observados, a conduta médica correta para dar prosseguimento ao cuidado com a criança é","tamanhos":{"questoes/9acac4ea1f47a396d887d7b839899d2a.png":14530}},{"id":"revalida_2024_1_q021","code":"REV-2024.1-Q021","imagens":[{"path":"questoes/1759f53850e813a5043c4f486fb94992.png","alt":"Tabela do exame de líquido cefalorraquidiano com resultado e valores de referência em unidades convencionais e do SI: contagem de células, glicose e proteína total.","sha256":"1622adbdc809dd05fd7b0bb5d47b90a60b444d184f95a55722930d5fb7012a2f","source_page":7}],"imagens_antes":[],"enunciado_antes_md5":"25862ea0e75c4a89cee15b17eaa456c6","enunciado_depois":"Um homem com 38 anos relata, em consulta, exantema, prurido, febre e artralgia que se resolveu em 72 horas com o uso de sintomáticos. O paciente conta que, após 10 dias, passou a apresentar parestesia em membros inferiores, que evoluiu para membros superiores em 24 horas. Ele conta que não buscou ajuda médica por julgar tratar-se de câimbras devido à falta de atividade física regular. Narra, ainda, que, após 3 dias, o quadro evoluiu com fraqueza nos membros inferiores, impedindo a deambulação, queixando-se também de cefaleia holocraniana e obstipação intestinal. Ao exame neurológico, apresenta-se vigil, orientado em tempo e espaço, com pupilas isocóricas e fotorreagentes, mobilidade ocular extrínseca preservada e demais pares cranianos sem alteração. Verificam-se, ainda: força muscular grau V/V em membros superiores e grau III/V em membros inferiores; reflexos bicipital, tricipital e estilorradial grau II/IV; reflexos patelar e aquileu abolidos; hipoestesia tátil e dolorosa nos quatro membros, com padrão de bota e luva; hipopalestesia em membros inferiores, até o tornozelo. O resultado do exame de líquido cefalorraquidiano (LCR) mostrou: Diante desse quadro clínico, qual é a principal suspeita diagnóstica?","tamanhos":{"questoes/1759f53850e813a5043c4f486fb94992.png":51263}},{"id":"revalida_2024_1_q036","code":"REV-2024.1-Q036","imagens":[{"path":"questoes/f9c391615b07d6a85aa1572454ae41cf.png","alt":"Tabela de exames laboratoriais com valor e valor de referência: hemograma (hematócrito, hemoglobina, plaquetas), bilirrubinas, função renal, eletrólitos, enzimas e CPK, e exame de urina.","sha256":"8a7d5d616169daf59dc0566e7f344cb6150c8c28d983b756d0aeb16f2bc330c2","source_page":11}],"imagens_antes":[],"enunciado_antes_md5":"d186be0bd582cb7b8c41bfa64f35b92d","enunciado_depois":"Um homem com 18 anos, residente em área urbana da região Sudeste, sujeita a inundação, chega ao pronto-socorro, durante período de chuvas, queixando-se de febre, mal-estar, mialgia e desconforto abdominal há 1 semana. Refere também que, há 4 dias, sentiu piora da mialgia e surgimento de colúria. Ao exame físico, apresenta-se: em estado geral regular, hidratado, hipocorado (++/4+), ictérico (+++/4+) e com sufusão hemorrágica conjuntival moderada, com temperatura axilar de 38 °C, frequência cardíaca de 110 bpm, pressão arterial de 110 X 70 mmHg. Verificam-se, ainda, dor à palpação dos músculos dos membros inferiores; abdome flácido, doloroso à palpação no hipocôndrio direito e presença de hepatomegalia. Os resultados dos exames laboratoriais registram: Diante do quadro clínico e laboratorial descrito, qual é a hipótese diagnóstica mais provável?","tamanhos":{"questoes/f9c391615b07d6a85aa1572454ae41cf.png":89169}},{"id":"revalida_2024_1_q077","code":"REV-2024.1-Q077","imagens":[{"path":"questoes/5a6826b3f52b13402a7cdc81c1c7047d.png","alt":"Tabela de exames laboratoriais do paciente com valor e valor de referência: hemoglobina, hematócrito, leucócitos, glicemia, enzimas hepáticas, bilirrubina, amilase, lipase, ureia, creatinina e cálcio.","sha256":"f0f1f04b2b49f6e242b3a0c62806ea78ceddba1b8f53c6e491b9554f921446a3","source_page":22}],"imagens_antes":[],"enunciado_antes_md5":"4106007f8ad21ed036a77dee41ba5af6","enunciado_depois":"Um paciente com 57 anos, queixa-se, em consulta, de dor abdominal difusa intermitente, há 3 meses, que piora com ingestão de alimentos, associada a emagrecimento de 9 quilogramas nesse período, além de diarreia com gotículas de gordura nas fezes. É tabagista e etilista há 30 anos. Ao exame físico, apresenta dor abdominal difusa que piora à palpação profunda em região mesogástrica, sem outras particularidades. Com base no quadro acima, quais são, respectivamente, o diagnóstico e a conduta para o paciente?","tamanhos":{"questoes/5a6826b3f52b13402a7cdc81c1c7047d.png":59689}},{"id":"revalida_2024_1_q091","code":"REV-2024.1-Q091","imagens":[{"path":"questoes/b01b4b7675afc982cb4a3d62d25f5e7f.png","alt":"Tabela de exames laboratoriais do paciente com valor e valor de referência: hematócrito, hemoglobina, leucócitos, neutrófilos, plaquetas, protrombina, ácido úrico, glicemia, creatinina, bilirrubina e lactato.","sha256":"3b83f40a05a7da330e4bfb262230009fcf3e33c3b8f7bf402b527c812f97cf32","source_page":25}],"imagens_antes":[],"enunciado_antes_md5":"807b048fc1d7e3cc453ada217bc62a0f","enunciado_depois":"Um paciente com 34 anos, em tratamento quimioterápico para linfoma, é avaliado no plantão de um hospital com queixa de dispneia, desconforto torácico, ortopneia, com progressão nas últimas 6 horas. Ao exame físico, apresenta-se em regular estado geral, com frequência cardíaca de 125 bpm, frequência respiratória de 28 irpm, saturação de O₂ de 93% em ar ambiente, pressão arterial de 86 x 48 mmHg. Durante a inspiração, observa-se que a pressão sistólica reduziu para 75 x 44 mmHg. A temperatura axilar do paciente é de 36,6 °C e ele apresenta grande distensão jugular, bulhas cardíacas hipofonéticas. O exame de ECG no leito indicou baixa voltagem dos complexos QRS, sem presença de alterações isquêmicas detectáveis. Os resultados de outros exames realizados nesse dia são: Considerando a hipótese diagnóstica mais provável, assinale a opção com as medidas mais adequadas a serem adotadas para esse paciente.","tamanhos":{"questoes/b01b4b7675afc982cb4a3d62d25f5e7f.png":60448}},{"id":"revalida_2024_2_q023","code":"REV-2024.2-Q023","imagens":[{"path":"questoes/f4e26dcc77158c8d5222c4dad49bed2a.png","alt":"Tabela de exames do recém-nascido com três colunas (exame laboratorial, resultado e valor de referência): hemoglobina, hematócrito, VCM, HCM, CHCM, plaquetas, reticulócitos, bilirrubinas e TSH.","sha256":"ed8fe7cc5e4d95e2b3fb6d25fe8350af977feb50474223af21b7888b8c6e638f","source_page":7}],"imagens_antes":[],"enunciado_antes_md5":"a36209debfc9d339b6f576c975236eec","enunciado_depois":"Um recém-nascido (RN) a termo, afrodescendente, do sexo masculino, com 26 dias, apresenta quadro de icterícia neonatal zona III de Kramer desde o 3.º dia de vida. Seus pais negam outras queixas e afirmam que ambos são consanguíneos (primos). Encontra-se em uso de fórmula láctea com ganho ponderal adequado. Não houve intercorrências na gestação e parto. Diante dessas informações, o médico solicita outros exames. A criança, então, retorna à consulta ambulatorial com propedêutica complementar solicitada há 7 dias. Os resultados dos exames realizados podem ser verificados a seguir. A tipagem sanguínea da mãe é O+ e do recém-nascido é A-. O Coombs direto (ou teste de antiglobulina direto) apresenta resultado negativo. Considerando-se o caso clínico e os exames complementares realizados, qual é a hipótese diagnóstica mais provável?","tamanhos":{"questoes/f4e26dcc77158c8d5222c4dad49bed2a.png":54012}},{"id":"revalida_2024_2_q046","code":"REV-2024.2-Q046","imagens":[{"path":"questoes/3a593073cbff1383b56e1195199de6e9.png","alt":"Dois eletrocardiogramas de 12 derivações, um acima do outro: o primeiro rotulado ECG Admissão e o segundo ECG após 30 minutos, conforme apresentados no enunciado.","sha256":"569e6fd726ed8f3b33b985d9f59036de2de5b42aa49b6353e272dde4899709de","source_page":13}],"imagens_antes":[{"alt":"Figura 1 da questão 46","url":"/question-assets/revalida_2024_2/q046_image_01.png","sha256":"c54c4ddb00ac022e6696fa3cefae0db50451dbb7d0f993e04ada87dc6c7f9d89","source_page":13}],"enunciado_antes_md5":"00cd9f054aa84d970a6af3736bd468e3","enunciado_depois":null,"tamanhos":{"questoes/3a593073cbff1383b56e1195199de6e9.png":1879548}},{"id":"revalida_2024_2_q060","code":"REV-2024.2-Q060","imagens":[{"path":"questoes/71fb567b5b74f3caeb76c1bcb57ba27e.png","alt":"Tabela de exames do paciente (hemoglobina, hematócrito, leucócitos, ureia, creatinina, HbA1c, glicemia, TGO, TGP e ECG), seguida do título Radiografia de tórax e de duas radiografias de tórax, (a) e (b).","sha256":"9a840237bb707653b02b2467ad082284333b88f4c88602cc1cfdc0a7131478bc","source_page":18}],"imagens_antes":[{"alt":"Figura 1 da questão 60","url":"/question-assets/revalida_2024_2/q060_image_01.png","sha256":"649dc80cb7aff6d56f7f34b93d5a6bdde51614fadb0c4e6d7e33eaed1c6cb65f","source_page":18}],"enunciado_antes_md5":"58d77d0e48fb274c1cd62c960e8132ec","enunciado_depois":"Um médico de família realiza uma visita domiciliar a um homem de 64 anos que está acamado e em tratamento para mal de Parkinson e hipertensão arterial. Durante a consulta, a filha do paciente relata que seu pai apresenta alterações de comportamento há 4 dias, estando mais prostrado e lentificado, com episódios de agitação noturna, sem outras queixas. Ao exame físico, notam-se estertores crepitantes em terço médio à direita, sem alteração percebida na ausculta cardíaca. Paciente sarcopênico e sem sinais de roda denteada. Apresenta, pressão arterial de 110 × 95 mmHg, frequência cardíaca de 96 batimentos por minuto, frequência respiratória de 13 incursões respiratórias por minuto, saturação de oxigêncio de 99% em ar ambiente e temperatura de 36,1 °C. O médico solicitou exames complementares, cujos resultados foram apresentados a ele três dias depois, no retorno da visita domiciliar. A consulta foi constatado que o idoso mantinha o mesmo quadro clínico pelo sétimo dia consecutivo. Apresentou os seguintes exames: A conduta terapêutica a ser adotada para o caso desse paciente é","tamanhos":{"questoes/71fb567b5b74f3caeb76c1bcb57ba27e.png":254316}},{"id":"revalida_2024_2_q066","code":"REV-2024.2-Q066","imagens":[{"path":"questoes/f0593ff8a6596585c62233416485c81d.png","alt":"Tabela de exames de controle de paciente com diabetes: ureia, creatinina, taxa de filtração glomerular, glicemia de jejum, hemoglobina glicada e albuminúria, com resultado e valor de referência, e nota sobre a fórmula CKD-EPI.","sha256":"08bb39a49fb9086379cf2e4364971a74de281b82349ec15dce65995a5df0823e","source_page":20}],"imagens_antes":[],"enunciado_antes_md5":"5ad35b16636e955f7ff055b93b04f020","enunciado_depois":"Um homem de 67 anos comparece à consulta de rotina. Diagnosticado com diabetes mellitus tipo 2 há cerca de 12 meses, em uso regular de metformina 500 mg de 12 em 12 horas. Possui história prévia de infarto agudo do miocárdio há 5 anos. Comparece à consulta de acompanhamento com exames laboratoriais de controle recentes, que apresentam resultados semelhantes aos exames anteriores, realizados há 3 e há 6 meses. A conduta recomendada para esse paciente é","tamanhos":{"questoes/f0593ff8a6596585c62233416485c81d.png":55511}},{"id":"revalida_2024_2_q073","code":"REV-2024.2-Q073","imagens":[{"path":"questoes/3268ad692a7fe1ce77be34a1ea7a0bf4.png","alt":"Três tabelas: exames do recém-nascido às 32 horas, exames após 4 horas de fototerapia e tabela de referência da bilirrubina total (mg/dL) para fototerapia e exsanguineotransfusão, por idade e idade gestacional.","sha256":"eeef0a3b5e9da75045ee6b52e8bde6e8b90593a75c71580d730b79fa17c064d9","source_page":21}],"imagens_antes":[],"enunciado_antes_md5":"dfe7748e5287c6a738a13866e5238c77","enunciado_depois":"Na maternidade, um recém-nascido (RN) de 30 horas de vida, evolui com icterícia zona 3 de Kramer. Nasceu com 36 semanas de idade gestacional (IG), de parto vaginal, tendo algumas equimoses durante o parto. A tipagem sanguínea da mãe é O- e do RN é B+. Os exames laboratoriais, realizados quando a criança estava com 32 horas de vida, revelam: Considerando-se o caso e a tabela de referência apresentados, a conduta médica adequada é","tamanhos":{"questoes/3268ad692a7fe1ce77be34a1ea7a0bf4.png":107501}},{"id":"revalida_2024_2_q076","code":"REV-2024.2-Q076","imagens":[{"path":"questoes/8c66eaf2ff5392b01964f0aa9ffddd59.png","alt":"Tabela de exames com quatro colunas (exame, amostra, resultado e valor de referência): ácido 5-hidroxiindolacético, normetanefrina e metanefrina na urina; TSH, T3 e T4 livre no sangue.","sha256":"206642d323a9328e003bc6fef7385f2fa2a3ac999e6523d4fd16804466c025d8","source_page":22}],"imagens_antes":[],"enunciado_antes_md5":"835d8e5f1e4791bb7e5515e2e63807f2","enunciado_depois":"Uma mulher de 24 anos procura atendimento hospitalar referindo quadro de cefaleia episódica, sudorese e taquicardia há 3 meses, com piora progressiva. Realizada a monitorização ambulatorial da pressão arterial (MAPA), identificou-se oscilação importante, caracterizando hipertensão paroxística. Definindo-se, como principal hipótese diagnóstica, a hipertensão arterial secundária, foram realizados os seguintes exames. Diante desses resultados, qual é a principal hipótese diagnóstica?","tamanhos":{"questoes/8c66eaf2ff5392b01964f0aa9ffddd59.png":43733}},{"id":"revalida_2025_1_q002","code":"REV-2025.1-Q002","imagens":[{"path":"questoes/3abe945538910fcc31d6712684227c11.png","alt":"Tabela de sinais vitais do paciente, com duas colunas (exame e resultado): frequência cardíaca, pressão arterial, frequência respiratória e temperatura axilar, cada uma com seu valor e unidade.","sha256":"be1497e53156c0e0b5e16f62e7e0679b94b49791a0db5716db7be7d57fc128a9","source_page":2}],"imagens_antes":[],"enunciado_antes_md5":"4b0fa8891a5b6f5fcdf1f151502455e7","enunciado_depois":"Homem de 42 anos, em uso crônico de anti-inflamatório não esteroide por doença reumática, dá entrada no pronto-socorro com 6 horas de evolução de dor epigástrica de forte intensidade. Sinais vitais: Ao exame físico, abdome tenso, com descompressão brusca dolorosa nos quatro quadrantes. O hemograma apresenta valores dentro da normalidade e a tomografia de abdome evidencia líquido livre intraperitoneal com ar no recesso hepatofrênico. Nesse caso, assinale a alternativa que apresenta a principal hipótese diagnóstica.","tamanhos":{"questoes/3abe945538910fcc31d6712684227c11.png":20745}},{"id":"revalida_2025_1_q021","code":"REV-2025.1-Q021","imagens":[{"path":"questoes/35482a9cb0cffcca7e7d3f1bef7543e1.png","alt":"Tabela de espirometria com quatro colunas: parâmetro, valor encontrado antes do broncodilatador, valor encontrado depois do broncodilatador e valor previsto. Linhas: VEF1, CVF e relação VEF1/CVF.","sha256":"14006672c2cd991466345310108cc44f1de1780466f2884149dd72c111ab6ff4","source_page":6}],"imagens_antes":[],"enunciado_antes_md5":"e445c9dfdd7d871b7e50d8b938cad7ae","enunciado_depois":"Homem de 55 anos procura atendimento em unidade básica de saúde (UBS) para renovar prescrição de losartana. Durante a consulta, relata dispneia aos esforços físicos moderados. Além disso, refere tosse pouco produtiva há alguns anos, o que atribui ao uso de 20 cigarros por dia há 20 anos. Radiografia do tórax revela alargamento dos espaços intercostais, sem outras alterações. Espirometria apresenta os seguintes resultados: Diante dos achados, define-se doença pulmonar obstrutiva crônica. Nesse caso, de acordo com os critérios GOLD, a doença do paciente pode ser funcionalmente classificada em","tamanhos":{"questoes/35482a9cb0cffcca7e7d3f1bef7543e1.png":43322}},{"id":"revalida_2025_1_q024","code":"REV-2025.1-Q024","imagens":[{"path":"questoes/73444fd87d4af14f63f4bbfd9069df3e.png","alt":"Tabela de sinais vitais maternos, com duas colunas (exame e resultado): frequência cardíaca materna, pressão arterial e saturação de oxigênio, cada uma com valor e unidade.","sha256":"6cb75f665d16ab32584adbfd14a17d95ece3b6aea41eba7c7a5f901b150f5462","source_page":7}],"imagens_antes":[],"enunciado_antes_md5":"f4342caf2da46e38f1183b70f36d20e3","enunciado_depois":"Mulher, G2P1 (parto vaginal), é conduzida ao serviço de urgência obstétrica por estar desacordada, após ter apresentado dor abdominal súbita e desmaio em casa. Está com 35 semanas de gestação e é hipertensa crônica em uso de metildopa e nifedipina. Está inconsciente, apresenta tônus uterino aumentado, com batimento cardíaco fetal de 50 bpm, colo uterino fechado e com moderado sangramento escuro por via vaginal. Ela apresenta os seguintes dados vitais: Diante desse quadro clínico, assinale a alternativa que apresenta, respectivamente, o diagnóstico e a conduta adequados.","tamanhos":{"questoes/73444fd87d4af14f63f4bbfd9069df3e.png":20064}},{"id":"revalida_2025_1_q029","code":"REV-2025.1-Q029","imagens":[{"path":"questoes/bfe89a7f6d71df3577d1ad9a4f2400ac.png","alt":"Duas tabelas na ordem da prova, com uma frase entre elas. A primeira traz sinais vitais e dados do exame físico (exame e resultado). A segunda traz o hemograma, com resultado e valor de referência para hematócrito, hemoglobina, leucócitos totais e plaquetas.","sha256":"992c723062b7e06bde20e1bc0c941ac15bd656d95979461d4435834ecb9ad3ed","source_page":8}],"imagens_antes":[],"enunciado_antes_md5":"9e3f5265ee507cc5001928f3163af84c","enunciado_depois":"Primigesta de 24 anos chega à maternidade com queixa de cefaleia, febre e dores articulares leves há 5 dias. Relata que ontem houve piora da febre e surgimento de manchas pelo corpo, o que a fez procurar a emergência. O obstetra verifica o cartão do pré-natal e constata que ela está com 22 semanas de gestação e já realizou 3 consultas na unidade básica de saúde (UBS), sempre com sinais vitais normais e exames laboratoriais sem alterações. Ao exame físico, a paciente apresenta-se em bom estado geral, lúcida e orientada. Durante a análise clínica, foram obtidos os seguintes resultados: Nesse caso, qual a principal hipótese diagnóstica e a conduta a ser adotada pelo obstetra?","tamanhos":{"questoes/bfe89a7f6d71df3577d1ad9a4f2400ac.png":73002}},{"id":"revalida_2025_1_q047","code":"REV-2025.1-Q047","imagens":[{"path":"questoes/2d22a6d21aca603614b65f0341103693.png","alt":"Tabela de sinais vitais do paciente, com duas colunas (exame e resultado): pressão arterial, frequência cardíaca e frequência respiratória, cada uma com valor e unidade.","sha256":"6ab9d8c9484b91184ecd0d852efebc6cf5a73ea28c16a7b22e42d04f6c73428e","source_page":13}],"imagens_antes":[],"enunciado_antes_md5":"dd550fd4499609c352a33161189f8bb8","enunciado_depois":"Homem de 35 anos, vítima de acidente de trânsito, com amputação traumática de membro inferior direito na região da perna, recebe atendimento no local do acidente. O exame clínico revela sangramento ativo e abundante na região da amputação. No momento, sua pele está pálida e fria, apresenta 13 pontos em Escala de Coma de Glasgow e seus sinais vitais são apresentados a seguir. Com base no protocolo do “X” ATLS, qual é a intervenção prioritária inicial para esse paciente?","tamanhos":{"questoes/2d22a6d21aca603614b65f0341103693.png":18741}},{"id":"revalida_2025_1_q051","code":"REV-2025.1-Q051","imagens":[{"path":"questoes/202abedbb814fee7bb4e9122cee7a073.png","alt":"Tabela de exames laboratoriais com três colunas (exame, resultado e valor de referência): leucócitos totais, hematócrito, plaquetas e teste rápido de antígeno NS1.","sha256":"90b92f6edf2c7954178e5993d1f1be64978f7526df6d7bbb699e0e5fd3a9a2e6","source_page":14}],"imagens_antes":[],"enunciado_antes_md5":"bc14034143c574b2f60e60152801ab45","enunciado_depois":"Homem de 25 anos vai à unidade de pronto atendimento (UPA) apresentando quadro de febre alta há 3 dias, associado a náuseas, mialgia, artralgia e leve dor em quadrantes superiores do abdome. Ao exame físico, o paciente encontra-se alerta, consciente e orientado; pressão arterial de 100 x 70 mmHg; frequência cardíaca de 110 bpm; e frequência respiratória de 18 irpm; pulsos cheios e extremidades quentes; fígado palpável a 3 centímetros do rebordo costal direito, levemente doloroso à palpação. Os exames laboratoriais iniciais do paciente revelam os seguintes resultados: Nesse caso, a conduta inicial mais adequada envolve","tamanhos":{"questoes/202abedbb814fee7bb4e9122cee7a073.png":33204}},{"id":"revalida_2025_1_q053","code":"REV-2025.1-Q053","imagens":[{"path":"questoes/6f9fa4e24169a25f6addc06947c45562.png","alt":"Tabela de hemograma com três colunas (exame, resultado e valor de referência): hemoglobina, hematócrito, volume corpuscular médio, hemoglobina corpuscular média e plaquetas, com as unidades.","sha256":"72c29516d7a27333d31a3e9e26c3086d32485a33db01e7a99012591eb3617893","source_page":14}],"imagens_antes":[],"enunciado_antes_md5":"2a9616db7228bd1e3423a7f7529f66eb","enunciado_depois":"Menina de 11 meses, nascida a termo é levada para avaliação médica pois a mãe está preocupada com o desenvolvimento da criança: está mais irritada, não senta sem apoio, não engatinha, e dorme pouco. A alimentação consiste de aleitamento materno complementado com a dieta da família, que é vegana. Faz suplementação de vitamina D (400 UI ao dia). O hemograma da criança revela leucócitos totais normais e diferencial de células sem alterações, além dos seguintes achados: Considerando o quadro descrito, a conduta adequada para essa criança é","tamanhos":{"questoes/6f9fa4e24169a25f6addc06947c45562.png":41252}},{"id":"revalida_2025_1_q054","code":"REV-2025.1-Q054","imagens":[{"path":"questoes/6bd235e7bbea835d5f62b0c5b762cce9.png","alt":"Tabela de hemograma com três colunas (exame, resultado e valor de referência): hemoglobina, hematócrito, leucócitos e plaquetas, com as unidades.","sha256":"1faea24c6e6e54e623c9b3f7e5352b6eae251ffc5f32b3a48bad8c5f9a8a1af4","source_page":15}],"imagens_antes":[],"enunciado_antes_md5":"eeb7cf62875543e2a053c3e1537503fe","enunciado_depois":"Mulher de 54 anos procura a unidade de pronto atendimento (UPA) com queixa de dor pélvica e de sangramento vaginal ativo, há 2 dias. Relata preocupação, pois não menstruava há 4 anos. Relata que a menopausa ocorreu aos 50 anos e que tem diabetes mellitus tipo 2, tratada com metformina desde os 41 anos. É sedentária, não fuma e nunca ingeriu bebidas alcoólicas. Apresentou os exames de mamografia e citologia de colo uterino, realizados há 4 meses, que mostraram BIRADS 2 bilateral na mamografia e citologia dentro dos limites da normalidade. Ao exame físico, a paciente encontra-se em bom estado geral, orientada, corada, com pressão arterial de 120 x 70 mmHg, frequência cardíaca de 69 bpm e índice de massa corporal (IMC) de 32,3 kg/m². O exame especular revela pequeno sangramento vermelho vivo, saindo pelo orifício cervical externo, com colo do útero atrófico e sem lesões visíveis. O hemograma realizado na UPA revela os seguintes resultados: Considerando o caso descrito, a conduta adequada é","tamanhos":{"questoes/6bd235e7bbea835d5f62b0c5b762cce9.png":26977}},{"id":"revalida_2025_1_q070","code":"REV-2025.1-Q070","imagens":[{"path":"questoes/e4e85582db152f998bbb44433d5145cf.png","alt":"Tabela de sinais vitais da paciente, com duas colunas (exame e resultado): pressão arterial, frequência cardíaca, frequência respiratória e saturação de oxigênio, cada uma com valor e unidade.","sha256":"19fe37f91373186f70cc8cd3b6be3dfa086dd4e9f73ddcdb1bbdb780d6a07093","source_page":18}],"imagens_antes":[],"enunciado_antes_md5":"8e97d4b62b54c23ecc086d0c666c13de","enunciado_depois":"Mulher de 67 anos chega a uma unidade básica de saúde (UBS) acompanhada pelo filho. Ele relata que a mãe, há cerca de 30 minutos, passou a apresentar intensa dor de cabeça e dificuldade para falar. A paciente é hipertensa, faz uso de anti-hipertensivos, estatina e antiagregante plaquetário em dose profilática. Há 6 anos, sofreu um acidente vascular cerebral (AVC) sem sequelas. Durante o exame físico, pontuou 14 na Escala de Coma de Glasgow e apresentou seguintes sinais vitais: Nessa situação, qual é a conduta adequada a ser adotada pelo médico da UBS?","tamanhos":{"questoes/e4e85582db152f998bbb44433d5145cf.png":26355}},{"id":"revalida_2025_1_q083","code":"REV-2025.1-Q083","imagens":[{"path":"questoes/a6a84e949d0118b023832ab41a29a7e2.png","alt":"Duas tabelas na ordem da prova, com um parágrafo entre elas: exames antes do tratamento e exames pós-tratamento, cada uma com resultado e valor de referência para hemoglobina, hematócrito, volume corpuscular médio e ferritina, mais a observação sobre anisocitose.","sha256":"8ef14bc0d7d7c578cdb2f6a09865f137d466745059f23cae9de662232a3759f3","source_page":21}],"imagens_antes":[],"enunciado_antes_md5":"e7eac0cc2a7e808f9afa479244a80dad","enunciado_depois":"Menina de 2 anos e 6 meses é atendida em uma unidade básica de saúde (UBS). A mãe relata que a criança consome cerca de um litro de leite de vaca por dia e ingere pouca carne. O médico observa palidez cutaneomucosa e solicita exames. Os resultados são apresentados a seguir. Com relação ao tratamento e à conduta desse paciente é correto afirmar que a","tamanhos":{"questoes/a6a84e949d0118b023832ab41a29a7e2.png":90048}},{"id":"revalida_2025_2_q010","code":"REV-2025.2-Q010","imagens":[{"path":"questoes/651305479fdf41fec179d7adbfaae1f3.png","alt":"Tabela de exames laboratoriais com três colunas (exame, resultado e valor de referência): hemoglobina, leucócitos, plaquetas, creatinina e ureia, com as unidades de cada medida.","sha256":"18386ecdf41bb7ea2cdeed445ec2cad87a7dcb65d86a86efd6124aa1eff2a456","source_page":4}],"imagens_antes":[],"enunciado_antes_md5":"081257464482d2b18166787f08ab3800","enunciado_depois":"Paciente feminina de 78 anos, com 24 horas de evolução de dor e abaulamento progressivo em região inguinal direita. Apresentou também alguns episódios de vômitos e diminuição da eliminação de flatos. Antecedentes: neoplasia de mama há 30 anos, diabetes mellitus há 20 anos e tabagista de 40 maços/ano. Ao exame estava normotensa, eucárdica, afebril, eupneica. Índice de massa corporal de 35 kg/m². Abdome globoso, depressível, com abaulamento não redutível e desconforto à palpação em região inguinal direita, com discreta hiperemia local e sem sinais de irritação peritoneal. Resultados dos exames laboratoriais: A hipótese diagnóstica mais provável é","tamanhos":{"questoes/651305479fdf41fec179d7adbfaae1f3.png":32648}},{"id":"revalida_2025_2_q015","code":"REV-2025.2-Q015","imagens":[{"path":"questoes/a8fd0f1e2b0d47b1cc2bed1936c5d686.png","alt":"Tabela com três colunas (exame, resultado e valor de referência): pressão arterial, peso, hematócrito, glicemia, albumina sérica, creatinina, triglicerídeos, proteína urinária de 24 horas e sedimentos da urina.","sha256":"3ae08319910dd59f208de03e8083ba1921b3074e798a82bcbb869ac68a40fd50","source_page":6}],"imagens_antes":[],"enunciado_antes_md5":"31b3c039978e1524d646f5ddbc0b544c","enunciado_depois":"Homem de 50 anos, queixando-se de astenia e constipação com fezes em fita. Há 15 dias, apresenta edema de membros inferiores até a raiz da região crural, bilateralmente, com pouca melhora à elevação dos membros. Ele perdeu 10 kg em 6 meses. Nega hipertensão arterial e diabetes mellitus e não faz uso de medicamento. Os exames do paciente apresentaram os seguintes resultados: Dentre esses achados laboratoriais, quais são necessários para a definição da síndrome renal do paciente?","tamanhos":{"questoes/a8fd0f1e2b0d47b1cc2bed1936c5d686.png":60636}},{"id":"revalida_2025_2_q024","code":"REV-2025.2-Q024","imagens":[{"path":"questoes/6eaa98552ffbb00ceedc19325c7e5a06.png","alt":"Tabela com três colunas (exame, resultado e valor de referência): hemoglobina, hematócrito, leucócitos totais, bastonetes, urina, hemácias e beta-hCG sérico, com as unidades de cada medida.","sha256":"54b5b64e404a3e7a83e303b91df27a3ec084764f61fbe865b794a9b704dc8d9f","source_page":8}],"imagens_antes":[],"enunciado_antes_md5":"211fc777e5b5c341d77fbfb6116ec22e","enunciado_depois":"Paciente do sexo feminino, 27 anos, é atendida em Unidade de Pronto Atendimento (UPA) com história de dor abdominal, com início em epigástrio há dois dias, contínua, sem fatores de melhora, associada a náuseas e perda de apetite, evoluindo para dor em fossa ilíaca direita há 1 dia e febre de 38,2 °C no dia do atendimento. Nega comorbidades, cirurgias prévias ou uso de medicações regulares. Relata que a última menstruação foi há 23 dias, e apresenta ciclos regulares de 28 dias. Exame físico: regular estado geral, corada, desidratada +/4+, eupneica, anictérica, acianótica; ausculta pulmonar e cardíaca sem alterações; ruídos hidroaéreos diminuídos, descompressão brusca dolorosa em quadrante inferior de abdome à direita. Considerando o diagnóstico mais provável, a conduta adequada é","tamanhos":{"questoes/6eaa98552ffbb00ceedc19325c7e5a06.png":40222}},{"id":"revalida_2025_2_q038","code":"REV-2025.2-Q038","imagens":[{"path":"questoes/4d1d7d2fecf9b4bc9a5dfc878bcf8366.png","alt":"Tabela com três colunas (exame, resultado e valor de referência) com 12 exames: hematócrito, hemoglobina, leucócitos, glicose, bilirrubina total, ureia, cálcio, amilase, lipase, fosfatase alcalina, LDH e TGO.","sha256":"ff47247444c5efe1dbd5fefc52f51a988eb695c57c8cc950a0f6c4ebba2cb06d","source_page":11}],"imagens_antes":[],"enunciado_antes_md5":"cc85fcd85d4a603e083f5459582588c0","enunciado_depois":"Homem de 58 anos deu entrada no pronto-socorro com dor epigástrica irradiada para as costas, iniciada há 2 horas, progressiva, pós-prandial, acompanhada de náuseas, vômitos e sudorese. Relata episódios semelhantes no último ano, que melhoraram com uso de analgésico. Tabagista ativo, alcoolista de 8 doses de destilado por dia há 33 anos, nega comorbidades. Exame físico: corado, acianótico, anictérico, sudoreico, fácies de dor, agitado. Índice de massa corporal de 23 kg/m²; pressão arterial de 150 x 90 mmHg; frequência cardíaca de 74 bpm; frequência respiratória de 18 irpm; temperatura axilar de 37 ºC. Abdome globoso, distendido, timpânico, peristalse presente, doloroso à palpação do epigástrio e hipocôndrio esquerdo. Os exames laboratoriais apresentam os seguintes resultados: Qual é o provável diagnóstico?","tamanhos":{"questoes/4d1d7d2fecf9b4bc9a5dfc878bcf8366.png":63753}},{"id":"revalida_2025_2_q041","code":"REV-2025.2-Q041","imagens":[{"path":"questoes/5c879218a90fb0661a489f98b26b9971.png","alt":"Tabela com três colunas (exame, resultado e valor de referência): glicemia, gasometria arterial (pH), bicarbonato, creatinina e potássio sérico, com as unidades de cada medida.","sha256":"f5673cee92725a1669d2877c57dfd295f880c48022aa7696638cabd1cee02f5f","source_page":12}],"imagens_antes":[],"enunciado_antes_md5":"fbd1b9a0e3959b5209b54bf92215f7ca","enunciado_depois":"Homem de 21 anos, portador de diabetes mellitus tipo 1, diagnosticado há 5 anos, foi levado à Unidade de Pronto Atendimento (UPA) devido à dor abdominal, náuseas e vômitos. Familiares informam que está sem utilizar insulina há 3 dias por dificuldades financeiras. No exame físico, encontra-se torporoso, desidratado, com hálito cetótico e dor abdominal à palpação profunda de forma generalizada. Ao exame, frequência cardíaca de 112 bpm; frequência respiratória de 38 irpm; pressão arterial de 110 x 70 mmHg. Os exames laboratoriais na admissão indicam: O diagnóstico e a conduta inicial indicada para esse paciente são, respectivamente,","tamanhos":{"questoes/5c879218a90fb0661a489f98b26b9971.png":32851}},{"id":"revalida_2025_2_q046","code":"REV-2025.2-Q046","imagens":[{"path":"questoes/d9b9a420c36a5c944ca380bd0fd4a8e1.png","alt":"Tabela de duas colunas, sem linha de cabeçalho, com o painel de autoanticorpos e o resultado de cada um: ANA (com título e padrão), anti-DNA dupla hélice, HLA-B27, fator reumatoide, anti-CCP, anti-Ro e anti-La.","sha256":"1d8299333b07e52fef4bed91b9264b6d5527eca70af5ecd474388d0f396bc1c4","source_page":13}],"imagens_antes":[],"enunciado_antes_md5":"cf8f48ad7649669b3ae9a6e2db7263a5","enunciado_depois":"Homem de 32 anos apresenta quadro de dor lombar crônica de início insidioso, com duração aproximada de 6 meses, que piora pela manhã e melhora com o movimento. Refere rigidez matinal, principalmente nas regiões lombar e sacroilíaca, com duração de mais de 30 minutos, com dor nas articulações sacroilíacas e sensação de fadiga durante as últimas semanas. Não há histórico de trauma. A história familiar é positiva para doenças reumatológicas, mas o paciente desconhece diagnósticos específicos. O painel de autoanticorpos apresenta: Com base no caso clínico e nos exames laboratoriais apresentados, qual é o diagnóstico mais provável?","tamanhos":{"questoes/d9b9a420c36a5c944ca380bd0fd4a8e1.png":45848}},{"id":"revalida_2025_2_q058","code":"REV-2025.2-Q058","imagens":[{"path":"questoes/8c163c8039e187cdceedab033a17c4c6.png","alt":"Traçado de eletrocardiograma na derivação D2, em papel quadriculado, apresentado no enunciado da questão.","sha256":"f42d654de535c59f9854acd840d94aea8bb8d177458063965a4a1dec845cdf80","source_page":15}],"imagens_antes":[],"enunciado_antes_md5":"f261fdb8b623094a05178712b66a16f4","enunciado_depois":null,"tamanhos":{"questoes/8c163c8039e187cdceedab033a17c4c6.png":238061}},{"id":"revalida_2025_2_q086","code":"REV-2025.2-Q086","imagens":[{"path":"questoes/c1da1e894b18eb850e82ed808071334b.png","alt":"Tabela com três colunas (exame, resultado e valor de referência): hematócrito, hemoglobina, reticulócitos, leucócitos, plaquetas, glicemia de jejum, colesterol total, HDL-C, triglicerídeos, esfregaço e ECG.","sha256":"58023eac17b9749d2ecab3af280937213cf82fb3762ff00dff090a27d7a537f9","source_page":22}],"imagens_antes":[],"enunciado_antes_md5":"9ba90bb432c4ad6e883eefb791e60d1a","enunciado_depois":"Em Unidade de Pronto Atendimento (UPA), mulher de 30 anos, negra, casada, refere vários episódios de dores nas pernas no último ano, às vezes com edema local, e dores torácicas, associadas à febre, coriza e tosse, apresentando melhora com paracetamol há 1 semana. Relata fortes dores em membros inferiores, intensidade 8/10, sem irradiação, e dor na região lombar, fadiga, indisposição e edema doloroso em tornozelo sem melhora, com utilização de analgésicos há 1 dia. Pai faleceu aos 40 anos devido a acidente vascular encefálico. Exame físico: eupneica; afebril; mucosas descoradas (++/4+); icterícia (+/4+). Sem alterações nos sinais vitais. Ausculta cardíaca com sopro sistólico (++/4+). Abdome plano, sem visceromegalias. Edema unilateral sem empastamento em tornozelo esquerdo (++/4+), associado à úlcera maleolar de 2 cm, com secreção purulenta e hiperemia nas bordas. Os exames laboratoriais apresentam os seguintes resultados: Qual achado no exame complementar confirma a principal hipótese diagnóstica para o caso?","tamanhos":{"questoes/c1da1e894b18eb850e82ed808071334b.png":71432}},{"id":"revalida_2026_1_q004","code":"REV-2026.1-Q004","imagens":[{"path":"questoes/c2565a1abddf2181b74b301f7e21badd.png","alt":"Tabela do exame de urina tipo I de gestante, com resultado e valor de referência de aspecto, densidade, pH, proteínas, nitrito, leucócitos, hemácias, células epiteliais e bactérias, e a linha da urocultura.","sha256":"3ac0e4fbd1d8449d98b08c8e01f6dfbfeec30022d18a0264a3d1d00744a8b2b7","source_page":3}],"imagens_antes":[],"enunciado_antes_md5":"af7d83cb2512118b493a47fc4acaf520","enunciado_depois":"Gestante de 30 anos, G2 P1, com 28 semanas de gestação, comparece à Unidade Básica de Saúde para consulta de rotina. Nega disúria, urgência miccional, dor suprapúbica, lombar, febre ou comorbidades. Traz exames solicitados da rotina pré-natal, cujos resultados são apresentados a seguir: Qual é a interpretação para os exames laboratoriais e o manejo adequado da paciente?","tamanhos":{"questoes/c2565a1abddf2181b74b301f7e21badd.png":48620}},{"id":"revalida_2026_1_q015","code":"REV-2026.1-Q015","imagens":[{"path":"questoes/6b6aab8301227b7b17a9b4ff3150fe63.png","alt":"Tabela de exames laboratoriais de adolescente, com resultado e valor de referência: hemoglobina, hematócrito, leucócitos, diferencial, plaquetas, TGO, TGP, ureia e creatinina.","sha256":"153f717ec83f14213d4b0f9d7980f43d7c56a27d786444d384733633fbea76b2","source_page":7}],"imagens_antes":[],"enunciado_antes_md5":"633b1abfadabee367a00339521b8a3e4","enunciado_depois":"Adolescente de 15 anos, sexo masculino, procura Unidade Básica de Saúde relatando manchas cutâneas pruriginosas iniciadas nas últimas 24 horas, comprometendo todo o corpo. Relata diagnóstico recente de amigdalite, tendo iniciado por conta própria ibuprofeno há 7 dias. Antecedente de asma na infância e rinite alérgica. Nega febre, tosse ou diarreia, bem como alergias anteriores a medicamentos ou alimentos. Ao exame físico, 36,8 °C, eupneico, corado, anictérico. PA 110 x 70 mmHg; FC 86 bpm, FR 14 irpm, SatO₂ 98% em ar ambiente. Pele com eritema difuso, simétrico, papular, principalmente em tronco, mas também em membros, poupando palmas e plantas. Sem lesões, adenomegalias cervicais, axilares ou inguinais. Cavidade oral sem alterações. Exames laboratoriais apresentam os seguintes resultados: Qual é a conduta mais adequada para o caso?","tamanhos":{"questoes/6b6aab8301227b7b17a9b4ff3150fe63.png":54186}},{"id":"revalida_2026_1_q017","code":"REV-2026.1-Q017","imagens":[{"path":"questoes/9f8aeaba7a98c9e73ab33807030c375e.png","alt":"Tabela de exames laboratoriais da admissão, com resultado e valor de referência de leucócitos e de proteína C reativa.","sha256":"bf64723107da6d15df0cfb09fda3a8641c6ab007d42e3687f426f9dc846b9678","source_page":7}],"imagens_antes":[],"enunciado_antes_md5":"5bd453bef7b65988c35c43280f24e9f4","enunciado_depois":"Mulher de 38 anos comparece a um serviço de emergência no 10º dia pós-operatório de cirurgia de obesidade (gastrectomia vertical). Queixa-se de dor abdominal progressiva, principalmente em epigástrio, náuseas com vômitos, inapetência e febre há dois dias. Ao exame, estado geral regular; FC 108 bpm; PA 110 x 70 mmHg; levemente desidratada; com dor à palpação profunda em andar superior do abdome e ausência de sinais de irritação peritoneal. Exames laboratoriais (admissão): A próxima conduta é","tamanhos":{"questoes/9f8aeaba7a98c9e73ab33807030c375e.png":15153}},{"id":"revalida_2026_1_q020","code":"REV-2026.1-Q020","imagens":[{"path":"questoes/bb802449cf741ccacad36c251d0b09ff.png","alt":"Tabela com número de casos novos e de óbitos entre os casos novos de quatro tipos de câncer em 2025: colorretal, estômago, mama e próstata.","sha256":"68c46c9c9c286dc9fcf6735318af33a982cd2561b98bdb20de6b28c3e57cca11","source_page":8}],"imagens_antes":[],"enunciado_antes_md5":"decfbc6e7ad673bcd5486031483921a7","enunciado_depois":"Um relatório de vigilância epidemiológica avaliou os casos notificados de quatro tipos de câncer em um município com 100 mil habitantes no ano de 2025. A tabela apresenta, para cada tipo, o número de casos notificados em 2025 e o número de óbitos entre esses casos no mesmo ano. Com base nesses resultados, qual câncer teve a maior letalidade do município, em 2025?","tamanhos":{"questoes/bb802449cf741ccacad36c251d0b09ff.png":26057}},{"id":"revalida_2026_1_q021","code":"REV-2026.1-Q021","imagens":[{"path":"questoes/ff3ad6b908c707a4af1e13b68e8d6099.png","alt":"Tabela de exames laboratoriais de criança de 4 anos, com resultado e valor de referência: EAS, urocultura, glicemia de jejum e ultrassonografia de rins e vias urinárias.","sha256":"8531a5ffa166e28cc543547348a413c19942cde38b9fb63222c10f8936339ecb","source_page":8}],"imagens_antes":[],"enunciado_antes_md5":"3bae0fae53edb0edea3c67d330412eb9","enunciado_depois":"Paciente, 4 anos, é levado à Unidade Básica de Saúde pelos pais com queixa de manter perda de urina durante a noite 1 a 2 vezes por semana, principalmente quando dorme profundamente, apesar de ter desenvolvido o controle esfincteriano diurno desde 3 anos e meio de idade. Não há histórico de infecção urinária, dor ao urinar, aumento da frequência urinária ou urgência miccional. Apresenta sono profundo, com dificuldade para despertar. Desenvolvimento neuropsicomotor adequado para a idade. Exame físico sem alterações. Exames laboratoriais: Qual é a principal hipótese diagnóstica?","tamanhos":{"questoes/ff3ad6b908c707a4af1e13b68e8d6099.png":24951}},{"id":"revalida_2026_1_q029","code":"REV-2026.1-Q029","imagens":[{"path":"questoes/366891f05e5d6f65d02b77ee79888f5f.png","alt":"Tabela de exames de admissão de homem com cirrose, com resultado e valor de referência de INR, plaquetas, creatinina e sódio.","sha256":"893f95c9994a5516ae09b261a6921a6dd93ec0a511cfd5f193107d658306a55d","source_page":11}],"imagens_antes":[],"enunciado_antes_md5":"028e0ce72834848e75e845a12dbc3b8f","enunciado_depois":"Homem, 52 anos, portador de cirrose hepática alcoólica, é admitido em Unidade de Emergência de um hospital secundário após apresentar rebaixamento do nível de consciência, iniciado há 24 horas. Chega confuso, desorientado, Glasgow 13, flapping positivo. Acompanhante refere aumento do volume abdominal nas últimas semanas. Ao exame físico, apresenta ascite volumosa, sem sinais de irritação peritoneal. Exames (admissão): Em relação à ascite, a conduta mais adequada é realizar","tamanhos":{"questoes/366891f05e5d6f65d02b77ee79888f5f.png":21333}},{"id":"revalida_2026_1_q040","code":"REV-2026.1-Q040","imagens":[{"path":"questoes/c90604bf002ed99338ad863448b85cd3.png","alt":"Tabela de exames de paciente com diabetes e hipertensão, com resultado e valor de referência: hemoglobina glicada, colesterol, triglicerídeos, creatinina, albuminúria e pressão arterial.","sha256":"5869b9943cea7999390233d36e7f2b5c224374978d86e090a23f3fa21cbca45b","source_page":13}],"imagens_antes":[],"enunciado_antes_md5":"2eb3a21906bcdd7f1107169ba9bca1d2","enunciado_depois":"Homem, 64 anos, aposentado, portador de diabetes mellitus, diagnosticada há 6 anos, e hipertensão arterial, diagnosticada recentemente. Faz uso de metformina 850 mg 3 vezes ao dia e losartana 50 mg/dia em dose única. É tabagista (30 maços/ano). Nega etilismo ou outras comorbidades. Pratica caminhadas de 30 minutos 3 vezes na semana. Traz os seguintes exames para avaliação: Para otimizar o tratamento medicamentoso deste paciente, que conjunto de medidas é mais adequado?","tamanhos":{"questoes/c90604bf002ed99338ad863448b85cd3.png":38594}},{"id":"revalida_2026_1_q066","code":"REV-2026.1-Q066","imagens":[{"path":"questoes/86460d370b35c676040adfb2ee1690dd.png","alt":"Tabela de exames iniciais de menina de 7 anos, com resultado e limites de normalidade: glicemia, pH arterial, bicarbonato, lactato, função renal, eletrólitos, leucócitos e plaquetas.","sha256":"a067d0b1bf457caa54fe9ec8caf65102e61f8f80becba67113127359a6c23b1e","source_page":19}],"imagens_antes":[],"enunciado_antes_md5":"2b182fd27f51670e8c7020f638bbc21d","enunciado_depois":"Menina, 7 anos, previamente saudável, é trazida pelos pais à Unidade de Pronto Atendimento de um hospital secundário devido à fadiga intensa há 3 dias, com piora progressiva. Nas últimas 24 horas, tornou-se muito sonolenta, com respiração rápida e profunda, descrita pelos pais como “barulhenta” e “ofegante”. Apresenta também dor abdominal difusa, náuseas e vômitos repetidos. Os pais negam tosse, febre e diarreia, mas relatam que a criança perdeu peso nas últimas semanas, apesar do aumento de apetite. Relatam aumento da ingesta de água e diurese abundante. Ao exame físico, a criança encontrava-se sonolenta; despertando com comandos verbais dos pais (Glasgow 13); mucosas secas; olhos encovados; FR 36 irpm, FC 138 bpm, PA 92 x 60 mmHg, SatO₂ 98% em ar ambiente; temperatura axilar 36,3 °C e enchimento capilar 2 segundos. Considerando-se o caso, qual é a conduta terapêutica indicada?","tamanhos":{"questoes/86460d370b35c676040adfb2ee1690dd.png":50422}},{"id":"revalida_2026_1_q072","code":"REV-2026.1-Q072","imagens":[{"path":"questoes/cec3377f3c8d0823ed9e6dcb91769e2d.png","alt":"Tabela de exames da admissão, com resultado e valor de referência: creatinina, ureia, potássio, sódio, pH, bicarbonato e pCO₂ da gasometria venosa, e eletrocardiograma.","sha256":"eccada9ee276a1fc9b2122e8dd24a57e072417481e5e3ae92c3fbfd364c31925","source_page":20}],"imagens_antes":[],"enunciado_antes_md5":"2a622a208065a941829bb2bb644688df","enunciado_depois":"Homem preto, 68 anos, com hipertensão arterial sistêmica, doença renal crônica estágio clínico 3a com creatinina basal de 1,4 mg/dL é levado ao Pronto Atendimento com náusea, tontura e mal-estar geral. Faz uso regular de anlodipino 10 mg/dia, furosemida 80 mg/dia e enalapril 20 mg/dia. Ao exame físico, apresenta PA 90 × 60 mmHg, FC 96 bpm, FR 20 irpm, SatO₂ 95% em ar ambiente, tempo de enchimento capilar de 4 segundos, sem outras alterações. Os exames da admissão estão no quadro abaixo: Com base nos dados do quadro, que condutas devem ser tomadas nesse momento?","tamanhos":{"questoes/cec3377f3c8d0823ed9e6dcb91769e2d.png":45058}},{"id":"revalida_2026_1_q073","code":"REV-2026.1-Q073","imagens":[{"path":"questoes/418a4438925b3a0e6776ed56e256c67b.png","alt":"Tabela do hemograma de menino de 5 anos, com resultado e valor de referência de leucócitos, hemoglobina, hematócrito e plaquetas, e duas notas de rodapé.","sha256":"17b6b78adc10452252912998de8582dab25814f782ee912e9b8469ca8bfe4f4f","source_page":21}],"imagens_antes":[],"enunciado_antes_md5":"c04aa98a5d101fc0a9009e167fd362ec","enunciado_depois":"Um menino de 5 anos, previamente saudável, é trazido à emergência com dor nos membros inferiores iniciada há 4 dias, dificuldade para correr e andar, e surgimento de petéquias no tronco inferior e pernas há 24 horas. Apresentou febre (38 °C) no 1º dia do quadro, sem outros sintomas respiratórios, gastrointestinais ou urinários. Mãe nega sangramentos espontâneos, perda de peso, palidez progressiva ou infecções recorrentes. Ao exame físico, bom estado geral, ativo, boa perfusão periférica. Desconforto ao movimentar os membros inferiores. Na pele, presença de petéquias dispersas, púrpuras, pequenas, não palpáveis e sem equimoses grandes. Ausência de visceromegalias e de linfonodomegalias. Os joelhos e tornozelos estão dolorosos à palpação, sem calor ou edema. Qual é o diagnóstico provável?","tamanhos":{"questoes/418a4438925b3a0e6776ed56e256c67b.png":34846}},{"id":"revalida_2026_1_q091","code":"REV-2026.1-Q091","imagens":[{"path":"questoes/999fdc97ab5002430d67119655913244.png","alt":"Tabela de exames laboratoriais, com resultado e valores de referência: bilirrubinas, AST, ALT, fosfatase alcalina, GGT, hemoglobina, reticulócitos, LDH e haptoglobina.","sha256":"c76520883355ca0be4bb5d754d5a149f10a0fc31ad1f7b6336118f2ac68a84b0","source_page":25}],"imagens_antes":[],"enunciado_antes_md5":"3e867b6ff0133bf11f92a7e3b7869976","enunciado_depois":"Homem, 26 anos, é avaliado em ambulatório de especialidades após encaminhamento da Atenção Primária à Saúde por 4 episódios de icterícia leve nos últimos 2 anos. Os episódios são autolimitados e exacerbam-se sob estresse físico, jejum prolongado ou privação de sono. O paciente nega perda ponderal, dor abdominal, colúria, acolia fecal, comorbidades, etilismo ou uso de medicamentos. Ao exame físico, apresenta-se em bom estado geral, com discreta icterícia de escleras, sem visceromegalias. Restante do exame físico normal. Durante investigação ambulatorial, foram solicitados exames laboratoriais, cujos resultados foram semelhantes aos exames realizados durante os episódios anteriores de icterícia: Com base no quadro clínico e laboratorial e uso adequado de recursos em saúde, o médico deve","tamanhos":{"questoes/999fdc97ab5002430d67119655913244.png":52397}},{"id":"revalida_2026_1_q096","code":"REV-2026.1-Q096","imagens":[{"path":"questoes/0bebdfe070bd8a9687e82d73e33c02f0.png","alt":"Tabela de exames laboratoriais de mulher de 68 anos, com resultado e valor de referência de hemoglobina, leucócitos, creatinina e proteína C reativa.","sha256":"557e658c27dba995e045aaf735edffa3fdf8eb45c1c37413680ff080522ed9a8","source_page":26}],"imagens_antes":[],"enunciado_antes_md5":"42c905ac177f68e3cbb3746bfe83e47b","enunciado_depois":"Mulher, 68 anos, procurou a Unidade de Pronto Atendimento com quadro de dor súbita, calor e edema importante em joelho direito, iniciado há 24 horas, que a impede de deambular. Faz acompanhamento regular por diabetes mellitus tipo 2 e osteoartrite de joelhos, em uso de metformina e gliclazida. Ao exame físico, apresenta bom estado geral, lúcida e orientada; PA 135 x 85 mmHg; FC 98 bpm; FR 18 irpm e temperatura axilar 37,9 ºC. O joelho direito apresenta-se com volumoso derrame articular, eritema e dor à mobilização passiva e ativa. Exames laboratoriais: Nessa situação, qual conduta deve ser adotada?","tamanhos":{"questoes/0bebdfe070bd8a9687e82d73e33c02f0.png":24990}},{"id":"revalida_2026_2_q022","code":"REV-2026.2-Q022","imagens":[{"path":"questoes/14a46487aefb6b9660ae082b35dfecf5.png","alt":"Tabela com colunas Exame, Resultado e Valor de referência: pH 7,36 (7,35 a 7,45); bicarbonato 22 mEq/L (22 a 26); osmolaridade plasmática 292 mOsm/kg (285 a 295); cetonemia e cetonúria ausentes; sódio 147 mEq/L (136 a 145); potássio 3,6 mEq/L (3,5 a 5,1).","sha256":"f1aa8c9fd5c1bce9e68c09846fcdcc5eca7a93792efb3f1c487b43c04751529c","source_page":7}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/14a46487aefb6b9660ae082b35dfecf5.png":38052}},{"id":"revalida_2026_2_q023","code":"REV-2026.2-Q023","imagens":[{"path":"questoes/11b5b649012b8cf0285cbec364057ac8.png","alt":"Tabela do hemograma com colunas Exame, Resultado e Valor de referência: hemoglobina 9,4 g/dL (10,5 a 14,2); volume corpuscular médio 68 fL (75 a 87); índice de anisocitose aumentado (sem valor de referência).","sha256":"3cb31a38a9ccfec72f80789e120648b3a15e1fdb223d2824a2370874afa1cb81","source_page":7}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/11b5b649012b8cf0285cbec364057ac8.png":18206}},{"id":"revalida_2026_2_q027","code":"REV-2026.2-Q027","imagens":[{"path":"questoes/b2e9ac5f505e9a57d9fe789e216295d2.png","alt":"Tabela 2 por 2 do teste rápido contra o padrão de referência: teste positivo 80 com diabetes presente e 20 com diabetes ausente (total 100); teste negativo 20 e 180 (total 200); totais 100, 200 e 300.","sha256":"7b22d3e58efcc88dba3948d17bb57828f6e03b20f4d40023c6f881922f2f0657","source_page":8}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/b2e9ac5f505e9a57d9fe789e216295d2.png":17412}},{"id":"revalida_2026_2_q029","code":"REV-2026.2-Q029","imagens":[{"path":"questoes/7145984642dc03b89ae6c6befb1fd864.png","alt":"Eletrocardiograma de 12 derivações em papel milimetrado, com as derivações DI, DII, DIII, aVR, aVL, aVF e V1 a V6 em tira contínua, mostrando o traçado do ritmo cardíaco.","sha256":"579414605de08c9dae3e8ee29b139151d7a6123473c567b420a560cdd1ca065d","source_page":9}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/7145984642dc03b89ae6c6befb1fd864.png":1217478}},{"id":"revalida_2026_2_q032","code":"REV-2026.2-Q032","imagens":[{"path":"questoes/a550013a3617f26e23da48678b6cffbd.png","alt":"Tabela da curva glicêmica (TOTG 75 g) com colunas Exame, Resultado e Valor de referência: jejum 89 mg/dL (< 92); 1 hora 182 mg/dL (< 180); 2 horas 152 mg/dL (< 153).","sha256":"7710fa6cf99763a2cbb61c277b464e02e9b2fecb2804054d2daf61fc93872eba","source_page":10}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/a550013a3617f26e23da48678b6cffbd.png":21130}},{"id":"revalida_2026_2_q034","code":"REV-2026.2-Q034","imagens":[{"path":"questoes/d248491459e1f3b3f7091bbaffc4a7ba.png","alt":"Tabela por ano, de 2019 a 2023, com casos novos de HIV diagnosticados no ano, total de pessoas vivendo com HIV em 31 de dezembro e óbitos relacionados à AIDS no ano (120/600/50; 125/670/35; 118/780/15; 122/890/5; 120/1.005/4).","sha256":"43f4f8bda234c468269c7f25f0e9927c03fe4ad082746a3c56dcd117652e2789","source_page":11}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/d248491459e1f3b3f7091bbaffc4a7ba.png":29522}},{"id":"revalida_2026_2_q037","code":"REV-2026.2-Q037","imagens":[{"path":"questoes/b510396ed7dfedebeeecc282f9f951ee.png","alt":"Diagrama de Lund-Browder: figuras do corpo humano de frente e de costas, divididas por linhas tracejadas em regiões com percentuais (1%, 2%, 1,5%, 13%, 2,5%, 1,75%) e letras A (cabeça), B (coxas) e C (pernas).","sha256":"03ae1ce1680a162dfb98f3c88c8b9587d567621258aa5772be531654818c4981","source_page":12},{"path":"questoes/a851e578d01ae7dfff769b1a45cdbab1.png","alt":"Tabela de referência para áreas variáveis (A, B e C) no diagrama de Lund-Browder, com a coluna 5 anos: área A 6,5%, área B 4,0% e área C 2,75%.","sha256":"7bf27dc3d00b4b033ccf58baaf9ae711a15186280552202b62f88f2c5859c25f","source_page":12}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/b510396ed7dfedebeeecc282f9f951ee.png":287653,"questoes/a851e578d01ae7dfff769b1a45cdbab1.png":12840}},{"id":"revalida_2026_2_q052","code":"REV-2026.2-Q052","imagens":[{"path":"questoes/8a34b7e176469af310728633dd9478eb.png","alt":"Fotografia do rosto de uma criança, com várias lesões avermelhadas e crostas amareladas ao redor do nariz, da boca e do queixo.","sha256":"8167235f59539c5babb04d26b1181714c293575152dbf1314316c4f65474f33d","source_page":15}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/8a34b7e176469af310728633dd9478eb.png":709238}},{"id":"revalida_2026_2_q053","code":"REV-2026.2-Q053","imagens":[{"path":"questoes/9c321b22cb87062b963c7e7f4a72430e.png","alt":"Radiografia frontal de tórax e abdome superior de recém-nascido, com material de contraste radiopaco visível na região superior do tórax, entre os campos pulmonares.","sha256":"c8e5b65599ed925d50f188e454b9765c18e157467617d8667214a1c35ed93f00","source_page":16}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/9c321b22cb87062b963c7e7f4a72430e.png":105159}},{"id":"revalida_2026_2_q059","code":"REV-2026.2-Q059","imagens":[{"path":"questoes/071a7250697b9b815d70db9e49c70d7d.png","alt":"Tabela do hemograma com colunas Exame, Resultado e Valor de referência: leucócitos 2.500/mm³; hemoglobina 8,0 g/dL; plaquetas 30.000/mm³; neutrófilos 500/mm³; linfócitos 1.800/mm³; blastos 5% (referência 0%).","sha256":"7b7cb228d05bd796ea36894335efa1e80a5fddecc848798506260150cae88ef5","source_page":17}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/071a7250697b9b815d70db9e49c70d7d.png":31272}},{"id":"revalida_2026_2_q067","code":"REV-2026.2-Q067","imagens":[{"path":"questoes/b81541a3310d60f9ae9e42c2e227a07f.png","alt":"Radiografia simples da pelve em incidência frontal na admissão, mostrando sacro, ossos ilíacos, articulações sacroilíacas, sínfise e quadris.","sha256":"047675c0b55ca5ad7039c5c6b9bcf2877d711fd743acd31a1a559676aaa84b1f","source_page":19}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/b81541a3310d60f9ae9e42c2e227a07f.png":90337}},{"id":"revalida_2026_2_q075","code":"REV-2026.2-Q075","imagens":[{"path":"questoes/8188ecf653539b4ba524129b09dafb64.png","alt":"Duas imagens de ultrassonografia transvaginal do ovário direito lado a lado: à esquerda em escala de cinza, com área central escura circundada por parede; à direita com Doppler colorido mostrando fluxo em azul e vermelho na periferia.","sha256":"088d31f9ef41396002e01a743b96b5061a9d5fea38bc47c7862e217dfbad15cb","source_page":21}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/8188ecf653539b4ba524129b09dafb64.png":445038}},{"id":"revalida_2026_2_q081","code":"REV-2026.2-Q081","imagens":[{"path":"questoes/254273f7bb768d9758bfaa7c09f68b30.png","alt":"Tabela do hemograma com colunas Exame, Resultado e Valor de referência: leucócitos 18.000/mm³; bastonetes 12%; neutrófilos 50%; linfócitos 20%; basófilos 3%, cada um com sua faixa de referência.","sha256":"936f4a2aafa6368d996c97bd1f7dadba4973d8438c800390d3d2820f630d189a","source_page":22},{"path":"questoes/2196c799da8ccca26252e8475246e6e6.png","alt":"Tomografia computadorizada axial de abdome superior mostrando o fígado e, no lobo direito, uma área arredondada de menor densidade, com contornos lobulados, junto à parede.","sha256":"e945f299b9541310dbc2cbb8cbbae5ec831d2121749b950d8359fb120e3fa32c","source_page":22}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/254273f7bb768d9758bfaa7c09f68b30.png":27305,"questoes/2196c799da8ccca26252e8475246e6e6.png":280915}},{"id":"revalida_2026_2_q082","code":"REV-2026.2-Q082","imagens":[{"path":"questoes/ccbce72be69dbb1f0d46b47b9ea02928.png","alt":"Tabela de exames com colunas Exame, Resultado e Valor de referência: hemoglobina 6,9 g/dL (12,0 a 15,1); volume corpuscular médio 67 fL (80 a 100); ferritina 5 ng/mL (20 a 200).","sha256":"dc7b8c0f4a3399b45317a41ea410fee3b0cedf2e5e398e046186dde340ab13f2","source_page":23}],"imagens_antes":[],"enunciado_antes_md5":null,"enunciado_depois":null,"tamanhos":{"questoes/ccbce72be69dbb1f0d46b47b9ea02928.png":18238}},{"id":"revalida_2026_2_q089","code":"REV-2026.2-Q089","imagens":[{"path":"questoes/105c8ce