,{"path":"questoes/366891f05e5d6f65d02b77ee79888f5f.png","tamanho":21333},{"path":"questoes/c90604bf002ed99338ad863448b85cd3.png","tamanho":38594},{"path":"questoes/86460d370b35c676040adfb2ee1690dd.png","tamanho":50422},{"path":"questoes/cec3377f3c8d0823ed9e6dcb91769e2d.png","tamanho":45058},{"path":"questoes/418a4438925b3a0e6776ed56e256c67b.png","tamanho":34846},{"path":"questoes/999fdc97ab5002430d67119655913244.png","tamanho":52397},{"path":"questoes/0bebdfe070bd8a9687e82d73e33c02f0.png","tamanho":24990},{"path":"questoes/14a46487aefb6b9660ae082b35dfecf5.png","tamanho":38052},{"path":"questoes/11b5b649012b8cf0285cbec364057ac8.png","tamanho":18206},{"path":"questoes/b2e9ac5f505e9a57d9fe789e216295d2.png","tamanho":17412},{"path":"questoes/7145984642dc03b89ae6c6befb1fd864.png","tamanho":1217478},{"path":"questoes/a550013a3617f26e23da48678b6cffbd.png","tamanho":21130},{"path":"questoes/d248491459e1f3b3f7091bbaffc4a7ba.png","tamanho":29522},{"path":"questoes/b510396ed7dfedebeeecc282f9f951ee.png","tamanho":287653},{"path":"questoes/a851e578d01ae7dfff769b1a45cdbab1.png","tamanho":12840},{"path":"questoes/8a34b7e176469af310728633dd9478eb.png","tamanho":709238},{"path":"questoes/9c321b22cb87062b963c7e7f4a72430e.png","tamanho":105159},{"path":"questoes/071a7250697b9b815d70db9e49c70d7d.png","tamanho":31272},{"path":"questoes/b81541a3310d60f9ae9e42c2e227a07f.png","tamanho":90337},{"path":"questoes/8188ecf653539b4ba524129b09dafb64.png","tamanho":445038},{"path":"questoes/254273f7bb768d9758bfaa7c09f68b30.png","tamanho":27305},{"path":"questoes/2196c799da8ccca26252e8475246e6e6.png","tamanho":280915},{"path":"questoes/ccbce72be69dbb1f0d46b47b9ea02928.png","tamanho":18238},{"path":"questoes/105c8cea1cf49740aa803417cf758fd2.png","tamanho":1708053},{"path":"questoes/42a947e765107da9edf937462a38c43b.png","tamanho":13124}]$carga_arquivos$::jsonb;
  v_marca constant text[] := array['revalida_2020_1_q079', 'revalida_2021_1_q099', 'revalida_2023_2_q063', 'revalida_2023_2_q096', 'revalida_2024_1_q069', 'revalida_2024_2_q011', 'revalida_2025_1_q001', 'revalida_2025_1_q076', 'revalida_2026_1_q027', 'revalida_2026_1_q068'];
  r jsonb;
  a jsonb;
  q public.questions;
  v_faltam text;
  v_n integer;
  v_paths text[];
  v_id text;
  v_ok text;
begin
  -- 1. os arquivos precisam estar no depósito (no banco de teste, sem o esquema storage, esta conferência não existe)
  if to_regclass('storage.objects') is not null then
    select count(*), string_agg(x ->> 'path', ', ') into v_n, v_faltam
    from jsonb_array_elements(v_arquivos) x
    where not exists (select 1 from storage.objects o where o.bucket_id = 'question-figures' and o.name = x ->> 'path'
                        and coalesce((o.metadata ->> 'size')::bigint, -1) = (x ->> 'tamanho')::bigint);
    if v_n > 0 then
      raise exception 'Faltam % de % imagens no depósito question-figures (ou com tamanho diferente). Rode antes o envio das imagens. Nada foi mudado. Primeiras: %',
        v_n, jsonb_array_length(v_arquivos), left(v_faltam, 400);
    end if;
  end if;
  -- 2. cada arquivo conferido (como o servidor faz depois de olhar o arquivo)
  for a in select value from jsonb_array_elements(v_arquivos) loop
    perform public.ch_worker_question_figure_confirm(a ->> 'path', 'image/png', (a ->> 'tamanho')::numeric);
  end loop;
  -- 3. cada questão
  perform set_config('sqie.reason', 'Carga das provas corrigidas (revisão de 12/10/2026): tabela como imagem e figuras que faltavam, recortadas do caderno oficial do Inep', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_imagens_resultado values (r ->> 'code', 'pulada', 'questão não encontrada no banco (a 2026/2 entra na parte 3)');
      continue;
    end if;
    v_paths := array(select i ->> 'path' from jsonb_array_elements(r -> 'imagens') i);
    if q.images = r -> 'imagens' and (r ->> 'enunciado_depois' is null or q.statement = r ->> 'enunciado_depois') then
      if not q.needs_image then update public.questions set needs_image = true where id = q.id; end if;
      insert into _carga_imagens_resultado values (q.code, 'já estava ligada', null);
      continue;
    end if;
    if q.images is distinct from r -> 'imagens_antes' then
      insert into _carga_imagens_resultado values (q.code, 'pulada', 'as figuras da questão mudaram depois de 12/10/2026');
      continue;
    end if;
    if r ->> 'enunciado_depois' is not null and md5(q.statement) is distinct from r ->> 'enunciado_antes_md5' then
      insert into _carga_imagens_resultado values (q.code, 'pulada', 'o enunciado não é o esperado (cole antes a parte 2 desta prova; ou alguém mudou o texto)');
      continue;
    end if;
    if exists (select 1 from public.question_figure_files f where f.path = any (v_paths) and (f.state <> 'confirmed' or (f.question_id is not null and f.question_id <> q.id))) then
      insert into _carga_imagens_resultado values (q.code, 'pulada', 'arquivo já liberado ou reservado a outra questão');
      continue;
    end if;
    update public.question_figure_files set question_id = q.id where path = any (v_paths);
    update public.questions set
      images = r -> 'imagens',
      statement = coalesce(r ->> 'enunciado_depois', statement),
      needs_image = true
    where id = q.id;
    perform public.admin_log('question.figure_set', q.id, jsonb_build_object('code', q.code, 'replaced', jsonb_array_length(q.images) > 0,
      'alt', (select string_agg(i ->> 'alt', ' | ') from jsonb_array_elements(r -> 'imagens') i), 'reason', 'Carga das provas corrigidas (revisão de 12/10/2026): tabela como imagem e figuras que faltavam, recortadas do caderno oficial do Inep'));
    insert into _carga_imagens_resultado values (q.code, 'ligada agora',
      jsonb_array_length(r -> 'imagens') || ' imagem(ns)' || case when r ->> 'enunciado_depois' is not null then '; trecho da tabela tirado do enunciado' else '' end
      || case when jsonb_array_length(q.images) > 0 then '; substituiu a imagem antiga' else '' end);
  end loop;
  -- 4. marca "cita figura" nas que já têm figura e estavam com a marca desligada
  foreach v_id in array v_marca loop
    update public.questions set needs_image = true where id = v_id and not needs_image returning code into v_ok;
    if found then insert into _carga_imagens_resultado values (v_ok, 'marca "cita figura" ligada', null); end if;
  end loop;
  perform set_config('sqie.reason', '', true);
end
$carga_imagens$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao = 'pulada') = 0 then 'OK: ' else 'ATENÇÃO: ' end
         || count(*) filter (where situacao = 'ligada agora') || ' questões ligadas agora, '
         || count(*) filter (where situacao = 'já estava ligada') || ' já estavam, '
         || count(*) filter (where situacao = 'pulada') || ' puladas (de 77); marcas "cita figura" ligadas: '
         || count(*) filter (where situacao like 'marca%') as resultado,
         null::text as detalhe
  from _carga_imagens_resultado
  union all
  select 1, 'PULADA: ' || questao, detalhe from _carga_imagens_resultado where situacao = 'pulada'
) x order by ordem, resultado;
